window.GITA=window.GITA||{};GITA.capitulos=GITA.capitulos||{};GITA.capitulos[8]={"numero": 8, "titulo": "El yoga del brahman imperecedero", "versos": [{"n": 1, "hablante": "arjuna", "sa": ["अर्जुन उवाच ।", "किं तद्ब्रह्म किमध्यात्मं किं कर्म पुरुषोत्तम ।", "अधिभूतं च किं प्रोक्तमधिदैवं किमुच्यते ॥१॥"], "iast": ["arjuna uvāca", "kiṃ tad brahma kim adhyātmaṃ kiṃ karma puruṣottama", "adhibhūtaṃ ca kiṃ proktam adhidaivaṃ kim ucyate"], "rojas": [], "t": "<span class=\"vt-parte\">¿Qué es ese <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>? ¿Qué es <a class=\"t\" href=\"glosario.html#adhyatma\" data-t=\"adhyatma\">lo relativo al sí-mismo</a>? ¿Qué es la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a>, oh <a class=\"t\" href=\"glosario.html#purusottama\" data-t=\"purusottama\">Puruṣottama</a>? ¿Y qué es lo que se llama <a class=\"t\" href=\"glosario.html#adhibhuta\" data-t=\"adhibhuta\">lo relativo a los seres</a>, y qué se denomina <a class=\"t\" href=\"glosario.html#adhidaiva\" data-t=\"adhidaiva\">lo relativo a los dioses</a>?</span>", "palabras": [{"iast": "arjunaḥ", "sa": "अर्जुनः", "gram": "nom. sg. m.", "es": "Arjuna", "ref": "arjuna"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "kim", "sa": "किम्", "gram": "nom. sg. n. interr.", "es": "qué"}, {"iast": "tat", "sa": "तत्", "gram": "nom. sg. n. pron.", "es": "ese"}, {"iast": "brahma", "sa": "ब्रह्म", "gram": "nom. sg. n.", "es": "brahman", "ref": "brahman"}, {"iast": "adhyātmam", "sa": "अध्यात्मम्", "gram": "nom. sg. n.", "es": "lo relativo al sí-mismo", "ref": "adhyatma", "analisis": "adhi (sobre, respecto de) + ātman (sí-mismo)"}, {"iast": "karma", "sa": "कर्म", "gram": "nom. sg. n.", "es": "la acción", "ref": "karma"}, {"iast": "puruṣottama", "sa": "पुरुषोत्तम", "gram": "voc. sg. m. comp.", "es": "oh Puruṣottama, Persona suprema", "analisis": "puruṣa (persona) + uttama (el más alto)"}, {"iast": "adhibhūtam", "sa": "अधिभूतम्", "gram": "nom. sg. n.", "es": "lo relativo a los seres", "ref": "adhibhuta", "analisis": "adhi (sobre, respecto de) + bhūta (ser, lo que ha llegado a ser)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "proktam", "sa": "प्रोक्तम्", "gram": "nom. sg. n. part. pf. pas.", "es": "se llama, se ha declarado", "analisis": "pra-√vac (declarar)"}, {"iast": "adhidaivam", "sa": "अधिदैवम्", "gram": "nom. sg. n.", "es": "lo relativo a los dioses", "ref": "adhidaiva", "analisis": "adhi (sobre, respecto de) + daiva (divino)"}, {"iast": "ucyate", "sa": "उच्यते", "gram": "3 sg. pres. pas.", "es": "se denomina", "analisis": "√vac (hablar)"}], "nota": "<p>Arjuna devuelve, en forma de preguntas, los términos con que terminó el capítulo anterior (<a class=\"vref\" href=\"capitulo-07.html#v29\" data-v=\"7.29\">7.29</a>–<a class=\"vref\" href=\"capitulo-07.html#v30\" data-v=\"7.30\">7.30</a>): Kṛṣṇa los había nombrado sin explicarlos. Entre este verso y el siguiente son siete preguntas (véase la interpretación). <em>Puruṣottama</em>, «la Persona suprema», aparece aquí por primera vez en la Gītā; el capítulo 15 explicará el nombre (<a class=\"vref\" href=\"capitulo-15.html#v18\" data-v=\"15.18\">15.18</a>–<a class=\"vref\" href=\"capitulo-15.html#v19\" data-v=\"15.19\">15.19</a>): Kṛṣṇa está más allá de lo perecedero y aun de lo imperecedero.</p>", "interp": [{"titulo": "Siete preguntas", "html": "<p>Las preguntas de 8.1–8.2 y sus respuestas forman el esqueleto del capítulo: (1) ¿qué es brahman? — lo <a class=\"t\" href=\"glosario.html#aksara\" data-t=\"aksara\">imperecedero</a> supremo; (2) ¿qué es lo relativo al sí-mismo? — la naturaleza propia; (3) ¿qué es la acción? — la <a class=\"t\" href=\"glosario.html#visarga\" data-t=\"visarga\">emisión</a> que hace surgir a los seres (<a class=\"vref\" href=\"capitulo-08.html#v3\" data-v=\"8.3\">8.3</a>); (4) ¿qué es lo relativo a los seres? — lo perecedero; (5) ¿qué, lo relativo a los dioses? — el puruṣa; (6) ¿quién es, y cómo, lo relativo al sacrificio en este cuerpo? — «yo mismo» (<a class=\"vref\" href=\"capitulo-08.html#v4\" data-v=\"8.4\">8.4</a>); (7) ¿cómo se te conoce en la hora de la muerte? A las seis primeras Kṛṣṇa responde en dos versos, con definiciones casi telegráficas; a la séptima dedica el resto del capítulo (<a class=\"vref\" href=\"capitulo-08.html#v5\" data-v=\"8.5\">8.5</a>–<a class=\"vref\" href=\"capitulo-08.html#v28\" data-v=\"8.28\">8.28</a>). Es la que de verdad le interesa a Arjuna, y la que da al capítulo su tono: qué se recuerda al morir y adónde lleva.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 2, "hablante": "arjuna", "sa": ["अधियज्ञः कथं कोऽत्र देहेऽस्मिन्मधुसूदन ।", "प्रयाणकाले च कथं ज्ञेयोऽसि नियतात्मभिः ॥२॥"], "iast": ["adhiyajñaḥ kathaṃ ko 'tra dehe 'smin madhusūdana", "prayāṇa-kāle ca kathaṃ jñeyo 'si niyatātmabhiḥ"], "rojas": [], "t": "<span class=\"vt-parte\">¿Quién es, y cómo, <a class=\"t\" href=\"glosario.html#adhiyajna\" data-t=\"adhiyajna\">lo relativo al sacrificio</a> aquí, en este cuerpo, oh <a class=\"t\" href=\"glosario.html#madhusudana\" data-t=\"madhusudana\">Madhusūdana</a>? ¿Y cómo te conocen en la hora de la muerte los que se dominan a sí mismos?</span>", "palabras": [{"iast": "adhiyajñaḥ", "sa": "अधियज्ञः", "gram": "nom. sg. m.", "es": "lo relativo al sacrificio", "ref": "adhiyajna", "analisis": "adhi (sobre, respecto de) + yajña (sacrificio)"}, {"iast": "katham", "sa": "कथम्", "gram": "ind.", "es": "cómo"}, {"iast": "kaḥ", "sa": "कः", "gram": "nom. sg. m. interr.", "es": "quién"}, {"iast": "atra", "sa": "अत्र", "gram": "ind.", "es": "aquí"}, {"iast": "dehe", "sa": "देहे", "gram": "loc. sg. m.", "es": "en el cuerpo"}, {"iast": "asmin", "sa": "अस्मिन्", "gram": "loc. sg. m. pron.", "es": "en este"}, {"iast": "madhusūdana", "sa": "मधुसूदन", "gram": "voc. sg. m.", "es": "oh Madhusūdana", "ref": "madhusudana"}, {"iast": "prayāṇa-kāle", "sa": "प्रयाणकाले", "gram": "loc. sg. m. comp.", "es": "en la hora de la muerte", "analisis": "prayāṇa (partida, marcha; pra-√yā) + kāla (tiempo, hora)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "jñeyaḥ", "sa": "ज्ञेयः", "gram": "nom. sg. m. part. fut. pas.", "es": "conocible, que ha de ser conocido", "analisis": "√jñā (conocer)"}, {"iast": "asi", "sa": "असि", "gram": "2 sg. pres.", "es": "eres", "analisis": "√as (ser)"}, {"iast": "niyatātmabhiḥ", "sa": "नियतात्मभिः", "gram": "instr. pl. m. comp.", "es": "por los que se dominan a sí mismos", "ref": "atman", "analisis": "niyata (sujeto, dominado; ni-√yam) + ātman (uno mismo, la mente): bahuvrīhi"}], "nota": "<p><em>Kathaṃ ko &#x27;tra</em>: «quién» es el adhiyajña y «cómo» está en el cuerpo; <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> advierte que no son dos preguntas, sino una sola con su modo, y así salen las siete que cuentan él y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> en <a class=\"vref\" href=\"capitulo-08.html#v1\" data-v=\"8.1\">8.1</a>–<a class=\"vref\" href=\"capitulo-08.html#v2\" data-v=\"8.2\">8.2</a>. <em>Prayāṇa-kāla</em>: «el tiempo de la partida», la hora de la muerte, como en <a class=\"vref\" href=\"capitulo-07.html#v30\" data-v=\"7.30\">7.30</a>. <em>Jñeyo &#x27;si</em>: «eres cognoscible», «has de ser conocido». <em>Niyatātman</em>: el que tiene sujeta la mente, el que se domina; <a class=\"vref\" href=\"capitulo-06.html#v14\" data-v=\"6.14\">6.14</a> y <a class=\"vref\" href=\"capitulo-06.html#v15\" data-v=\"6.15\">6.15</a> piden lo mismo al que medita.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 3, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "अक्षरं ब्रह्म परमं स्वभावोऽध्यात्ममुच्यते ।", "भूतभावोद्भवकरो विसर्गः कर्मसंज्ञितः ॥३॥"], "iast": ["śrī-bhagavān uvāca", "akṣaraṃ brahma paramaṃ svabhāvo 'dhyātmam ucyate", "bhūta-bhāvodbhava-karo visargaḥ karma-saṃjñitaḥ"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">Brahman es lo <a class=\"t\" href=\"glosario.html#aksara\" data-t=\"aksara\">imperecedero</a> supremo; la <a class=\"t\" href=\"glosario.html#svabhava\" data-t=\"svabhava\">naturaleza propia</a> se llama <a class=\"t\" href=\"glosario.html#adhyatma\" data-t=\"adhyatma\">lo relativo al sí-mismo</a>; y la <a class=\"t\" href=\"glosario.html#visarga\" data-t=\"visarga\">emisión</a> que hace surgir la existencia de los seres recibe el nombre de <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a>.</span>", "palabras": [{"iast": "śrī-bhagavān", "sa": "श्रीभगवान्", "gram": "nom. sg. m. comp.", "es": "el glorioso Señor", "ref": "bhagavan", "analisis": "śrī (gloria) + bhagavat (el Señor)"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "akṣaram", "sa": "अक्षरम्", "gram": "nom. sg. n.", "es": "lo imperecedero", "ref": "aksara", "analisis": "a (no) + kṣara (que fluye, perecedero; √kṣar)"}, {"iast": "brahma", "sa": "ब्रह्म", "gram": "nom. sg. n.", "es": "brahman", "ref": "brahman"}, {"iast": "paramam", "sa": "परमम्", "gram": "nom. sg. n.", "es": "supremo"}, {"iast": "svabhāvaḥ", "sa": "स्वभावः", "gram": "nom. sg. m.", "es": "la naturaleza propia", "ref": "svabhava", "analisis": "sva (propio) + bhāva (ser, modo de ser)"}, {"iast": "adhyātmam", "sa": "अध्यात्मम्", "gram": "nom. sg. n.", "es": "lo relativo al sí-mismo", "ref": "adhyatma"}, {"iast": "ucyate", "sa": "उच्यते", "gram": "3 sg. pres. pas.", "es": "se llama", "analisis": "√vac (hablar)"}, {"iast": "bhūta-bhāvodbhava-karaḥ", "sa": "भूतभावोद्भवकरः", "gram": "nom. sg. m. comp.", "es": "que hace surgir la existencia de los seres", "analisis": "bhūta (ser) + bhāva (existencia, estado) + udbhava (surgimiento; ud-√bhū) + kara (que hace; √kṛ)"}, {"iast": "visargaḥ", "sa": "विसर्गः", "gram": "nom. sg. m.", "es": "la emisión", "ref": "visarga", "analisis": "vi-√sṛj (soltar, emitir)"}, {"iast": "karma-saṃjñitaḥ", "sa": "कर्मसंज्ञितः", "gram": "nom. sg. m. comp.", "es": "recibe el nombre de acción", "ref": "karma", "analisis": "karman (acción) + saṃjñita (llamado; saṃjñā, «nombre»)"}], "nota": "<p><em>Akṣara</em> significa «imperecedero» (de <em>a-</em> y √<em>kṣar</em>, «fluir, desgastarse») y también «sílaba»; aquí lo precisa <em>paramam</em>, «supremo»: es brahman mismo (véase la ficha). <em>Svabhāva</em>, «naturaleza propia» o «ser propio»: el texto no dice de qué; los comentaristas lo completan de modos distintos (véanse la alternativa y la ficha <a class=\"t\" href=\"glosario.html#adhyatma\" data-t=\"adhyatma\">adhyātma</a>). <em>Visarga</em>, de vi-√<em>sṛj</em>, «soltar, emitir», es la emisión o el desprendimiento: en el ritual, la ofrenda que se suelta en el fuego; en la cosmología, la emisión creadora. <em>Bhūta-bhāvodbhava-kara</em>: «que produce el surgimiento de la existencia de los seres».</p>", "interp": [{"titulo": "Lo imperecedero es el sí-mismo supremo", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende <em>akṣara</em> como el sí-mismo supremo, lo que no perece, y no como la sílaba <em>oṃ</em>, que el texto nombra aparte más adelante (<a class=\"vref\" href=\"capitulo-08.html#v13\" data-v=\"8.13\">8.13</a>); además, el adjetivo «supremo» conviene mejor a brahman. Lo relaciona, como <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, con la enseñanza de Yājñavalkya a Gārgī sobre «este imperecedero» en la <em>Bṛhad-āraṇyaka Upaniṣad</em>. La naturaleza propia es el mismo brahman en cuanto sí-mismo interior de cada cuerpo; la acción, la ofrenda del sacrificio que pone en marcha el ciclo de los seres.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Lo imperecedero y la naturaleza", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lee el verso desde la clasificación de los aspirantes de <a class=\"vref\" href=\"capitulo-07.html#v29\" data-v=\"7.29\">7.29</a>–<a class=\"vref\" href=\"capitulo-07.html#v30\" data-v=\"7.30\">7.30</a>: el que busca librarse de la vejez y de la muerte ha de conocer lo imperecedero, el sí-mismo en su forma pura, libre de la naturaleza; «lo relativo al sí-mismo» es para él la naturaleza material unida al sí-mismo, con sus impresiones, de la que hay que liberarse; y la acción, la emisión del semen en la unión con la mujer, que da origen a los cuerpos de los seres y de la que el aspirante ha de apartarse (de ahí la castidad de <a class=\"vref\" href=\"capitulo-08.html#v11\" data-v=\"8.11\">8.11</a>).</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Brahman es lo imperecedero supremo; su ser propio, presente en cada cuerpo como el sí-mismo interior, se llama lo relativo al sí-mismo; y la ofrenda que, en el sacrificio, hace surgir a los seres recibe el nombre de acción.", "nota": "<p>Con <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, a quien sigue <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> entiende igual el <em>visarga</em>. <em>Svabhāva</em> es para él el ser propio de ese mismo brahman supremo, que está en cada cuerpo como su sí-mismo interior; y el <em>visarga</em> es la ofrenda que se suelta para los dioses en el sacrificio, que por la lluvia y el alimento da origen a los seres (como en <a class=\"vref\" href=\"capitulo-03.html#v14\" data-v=\"3.14\">3.14</a>). La traducción principal deja abiertos los dos términos.</p>"}], "ens": "las-definiciones-de-krsna"}, {"n": 4, "hablante": "krsna", "sa": ["अधिभूतं क्षरो भावः पुरुषश्चाधिदैवतम् ।", "अधियज्ञोऽहमेवात्र देहे देहभृतां वर ॥४॥"], "iast": ["adhibhūtaṃ kṣaro bhāvaḥ puruṣaś cādhidaivatam", "adhiyajño 'ham evātra dehe deha-bhṛtāṃ vara"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Lo relativo a los seres es lo perecedero; lo relativo a los dioses, el <a class=\"t\" href=\"glosario.html#purusa\" data-t=\"purusa\">puruṣa</a>; y lo relativo al sacrificio soy yo mismo, aquí, en el cuerpo, oh tú, el mejor de los que tienen cuerpo.</span>", "palabras": [{"iast": "adhibhūtam", "sa": "अधिभूतम्", "gram": "nom. sg. n.", "es": "lo relativo a los seres", "ref": "adhibhuta"}, {"iast": "kṣaraḥ", "sa": "क्षरः", "gram": "nom. sg. m. adj.", "es": "perecedero", "analisis": "√kṣar (fluir, desgastarse)"}, {"iast": "bhāvaḥ", "sa": "भावः", "gram": "nom. sg. m.", "es": "el ser, lo que existe", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "puruṣaḥ", "sa": "पुरुषः", "gram": "nom. sg. m.", "es": "el puruṣa", "ref": "purusa"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "adhidaivatam", "sa": "अधिदैवतम्", "gram": "nom. sg. n.", "es": "lo relativo a los dioses", "ref": "adhidaiva", "analisis": "adhi (sobre, respecto de) + daivata (divinidad)"}, {"iast": "adhiyajñaḥ", "sa": "अधियज्ञः", "gram": "nom. sg. m.", "es": "lo relativo al sacrificio", "ref": "adhiyajna"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "mismo, precisamente"}, {"iast": "atra", "sa": "अत्र", "gram": "ind.", "es": "aquí"}, {"iast": "dehe", "sa": "देहे", "gram": "loc. sg. m.", "es": "en el cuerpo"}, {"iast": "deha-bhṛtām", "sa": "देहभृताम्", "gram": "gen. pl. m. comp.", "es": "de los que tienen cuerpo", "analisis": "deha (cuerpo) + bhṛt (que lleva; √bhṛ)"}, {"iast": "vara", "sa": "वर", "gram": "voc. sg. m.", "es": "oh el mejor"}], "nota": "<p><em>Kṣaro bhāvaḥ</em>: «el ser perecedero», todo lo que nace y se deshace. <em>Puruṣa</em>, aquí sin más precisión: las escuelas lo identifican de modos distintos (véase la ficha <a class=\"t\" href=\"glosario.html#adhidaiva\" data-t=\"adhidaiva\">adhidaiva</a>). <em>Adhidaivata</em> es la forma que el verso usa en lugar de <em>adhidaiva</em>. <em>Deha-bhṛtāṃ vara</em>, «el mejor de los que llevan cuerpo», es un vocativo de elogio para Arjuna; no se repite en la Gītā.</p>", "interp": [{"titulo": "Hiraṇyagarbha y Viṣṇu", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, a quien sigue aquí casi a la letra <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, lo relativo a los seres es todo lo que tiene origen; el puruṣa, lo relativo a los dioses, es Hiraṇyagarbha, el ser que está en el sol y que asiste a las facultades de todos los seres; y lo relativo al sacrificio es Viṣṇu, la divinidad de todo sacrificio, que Kṛṣṇa dice ser él mismo. Está «en el cuerpo» porque el sacrificio se realiza con el cuerpo.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "De lo cósmico a «yo»", "html": "<p>Las respuestas de 8.3–8.4 descienden por los planos de la realidad —lo absoluto, la persona, la acción, los seres, los dioses, el sacrificio— y terminan en un pronombre: «yo mismo». Igual que en el capítulo 7, donde todo estaba «ensartado» en Kṛṣṇa (<a class=\"vref\" href=\"capitulo-07.html#v7\" data-v=\"7.7\">7.7</a>), las categorías de la tradición védica quedan referidas a él. La séptima pregunta, la de la hora de la muerte, queda para los versos siguientes.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Lo relativo a los seres es lo perecedero; lo relativo a los dioses, el puruṣa; y lo relativo al sacrificio soy yo mismo, que habito aquí, en el cuerpo de cada uno, como su guía interior, oh tú, el mejor de los que tienen cuerpo.", "nota": "<p><em>Atra dehe</em>, «aquí, en el cuerpo», puede entenderse de varias maneras: el sacrificio se realiza con el cuerpo, y por eso su divinidad está «en el cuerpo» (<a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>); o el Señor habita en el cuerpo de cada ser como guía interior (<em>antaryāmin</em>) y es él quien preside el sacrificio, mueve a realizarlo y da su fruto (así <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>; <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> lo ve presente en el cuerpo de todos los seres como el que disfruta de todo sacrificio). <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> da una tercera lectura: el cuerpo es el de Indra y los demás dioses, que son cuerpo de Kṛṣṇa, y él es su sí-mismo, a quien se adora en los sacrificios. La traducción principal conserva la concisión del original.</p>"}], "ens": "las-definiciones-de-krsna"}, {"n": 5, "hablante": "krsna", "sa": ["अन्तकाले च मामेव स्मरन्मुक्त्वा कलेवरम् ।", "यः प्रयाति स मद्भावं याति नास्त्यत्र संशयः ॥५॥"], "iast": ["anta-kāle ca mām eva smaran muktvā kalevaram", "yaḥ prayāti sa mad-bhāvaṃ yāti nāsty atra saṃśayaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Y quien, en la hora final, parte dejando el cuerpo mientras me <a class=\"t\" href=\"glosario.html#smarana\" data-t=\"smarana\">recuerda</a> sólo a mí, llega a mi ser: no hay en ello <a class=\"t\" href=\"glosario.html#samsaya\" data-t=\"samsaya\">duda</a>.</span>", "palabras": [{"iast": "anta-kāle", "sa": "अन्तकाले", "gram": "loc. sg. m. comp.", "es": "en la hora final", "analisis": "anta (fin) + kāla (tiempo, momento)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "mām", "sa": "माम्", "gram": "acc. sg. pron.", "es": "a mí"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "sólo"}, {"iast": "smaran", "sa": "स्मरन्", "gram": "nom. sg. m. part. pres.", "es": "recordando", "ref": "smarana", "analisis": "√smṛ (recordar, tener presente)"}, {"iast": "muktvā", "sa": "मुक्त्वा", "gram": "ger.", "es": "dejando", "analisis": "√muc (soltar, dejar)"}, {"iast": "kalevaram", "sa": "कलेवरम्", "gram": "acc. sg. n.", "es": "el cuerpo"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. pron. rel.", "es": "quien"}, {"iast": "prayāti", "sa": "प्रयाति", "gram": "3 sg. pres. act.", "es": "parte, se va", "analisis": "pra-√yā (partir)"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ése"}, {"iast": "mad-bhāvam", "sa": "मद्भावम्", "gram": "acc. sg. m. comp.", "es": "mi ser, mi condición", "analisis": "mad (yo) + bhāva (ser, estado)"}, {"iast": "yāti", "sa": "याति", "gram": "3 sg. pres. act.", "es": "llega a", "analisis": "√yā (ir)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "asti", "sa": "अस्ति", "gram": "3 sg. pres. act.", "es": "hay", "analisis": "√as (ser)"}, {"iast": "atra", "sa": "अत्र", "gram": "ind.", "es": "en esto"}, {"iast": "saṃśayaḥ", "sa": "संशयः", "gram": "nom. sg. m.", "es": "duda", "ref": "samsaya"}], "nota": "<p><em>Anta-kāla</em>, «el tiempo del fin», es la hora de la muerte; <a class=\"vref\" href=\"capitulo-08.html#v10\" data-v=\"8.10\">8.10</a> la llama <em>prayāṇa-kāla</em>, «la hora de la partida». <em>Kalevara</em> es una palabra poética para «cuerpo». <em>Mad-bhāva</em>, «mi ser» o «mi condición», es lo que se alcanza: no un lugar, sino un modo de ser, como en <a class=\"vref\" href=\"capitulo-04.html#v10\" data-v=\"4.10\">4.10</a>. El verso responde a la última de las preguntas de Arjuna: cómo se conoce a Kṛṣṇa en la hora de la muerte (<a class=\"vref\" href=\"capitulo-08.html#v2\" data-v=\"8.2\">8.2</a>).</p>", "interp": [{"titulo": "Mi ser", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende <em>mad-bhāvam</em> como «la realidad de Viṣṇu» (<em>vaiṣṇavaṃ tattvam</em>), el Señor supremo: quien muere recordándolo sólo a él alcanza esa realidad. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> glosan «mi forma» (<em>mad-rūpatā</em>); para Madhusūdana, quien meditó en el Señor con atributos llega a ella después de pasar por el mundo de Hiraṇyagarbha.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "lo-que-se-recuerda-al-morir"}, {"n": 6, "hablante": "krsna", "sa": ["यं यं वापि स्मरन्भावं त्यजत्यन्ते कलेवरम् ।", "तं तमेवैति कौन्तेय सदा तद्भावभावितः ॥६॥"], "iast": ["yaṃ yaṃ vāpi smaran bhāvaṃ tyajaty ante kalevaram", "taṃ tam evaiti kaunteya sadā tad-bhāva-bhāvitaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Sea cual sea el estado que uno recuerda cuando al fin deja el cuerpo, a ése mismo va, oh <a class=\"t\" href=\"glosario.html#kaunteya\" data-t=\"kaunteya\">Kaunteya</a>, porque siempre ha vivido impregnado de él.</span>", "palabras": [{"iast": "yaṃ yaṃ", "sa": "यं यं", "gram": "acc. sg. m. pron. rel. (repetido)", "es": "cualquiera que"}, {"iast": "vā api", "sa": "वा अपि", "gram": "ind.", "es": "o también"}, {"iast": "smaran", "sa": "स्मरन्", "gram": "nom. sg. m. part. pres.", "es": "recordando", "ref": "smarana", "analisis": "√smṛ (recordar)"}, {"iast": "bhāvam", "sa": "भावम्", "gram": "acc. sg. m.", "es": "estado, modo de ser", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "tyajati", "sa": "त्यजति", "gram": "3 sg. pres. act.", "es": "deja", "analisis": "√tyaj (abandonar)"}, {"iast": "ante", "sa": "अन्ते", "gram": "loc. sg. m.", "es": "al final"}, {"iast": "kalevaram", "sa": "कलेवरम्", "gram": "acc. sg. n.", "es": "el cuerpo"}, {"iast": "taṃ tam", "sa": "तं तम्", "gram": "acc. sg. m. pron. (repetido)", "es": "a ese mismo"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente"}, {"iast": "eti", "sa": "एति", "gram": "3 sg. pres. act.", "es": "va", "analisis": "√i (ir)"}, {"iast": "kaunteya", "sa": "कौन्तेय", "gram": "voc. sg. m.", "es": "oh Kaunteya", "ref": "kaunteya"}, {"iast": "sadā", "sa": "सदा", "gram": "ind.", "es": "siempre"}, {"iast": "tad-bhāva-bhāvitaḥ", "sa": "तद्भावभावितः", "gram": "nom. sg. m. comp.", "es": "impregnado de ese estado", "analisis": "tad (ese) + bhāva (estado) + bhāvita (impregnado, cultivado; ppp. caus. de √bhū, «hecho ser»)"}], "nota": "<p><em>Bhāva</em> es a la vez «estado», «modo de ser» y la idea o el sentimiento en que uno está absorto. El verso enuncia una regla general —se va a aquello que se recuerda al morir— de la que el anterior era un caso: si lo que se recuerda es Kṛṣṇa, se llega a él.</p>", "interp": [{"titulo": "Como es la voluntad, así se es", "html": "<p>La regla tiene raíces en las Upaniṣads. La <em>Chāndogya</em> (3.14.1) dice que el hombre está hecho de su resolución (<em>kratu</em>): tal como es su resolución en este mundo, así llega a ser al partir de él. La <em>Praśna</em> (3.10) añade que el pensamiento con que uno muere es el que lo lleva, con el aliento, al mundo que se ha figurado.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "El rey que pensaba en un ciervo", "html": "<p>Prabhupāda ilustra el verso, en su comentario, con la historia del rey Bharata (ya <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> la evoca al comentar <a class=\"vref\" href=\"capitulo-08.html#v5\" data-v=\"8.5\">8.5</a> y <a class=\"vref\" href=\"capitulo-08.html#v8\" data-v=\"8.8\">8.8</a>), que el <em>Bhāgavata Purāṇa</em> (5.8) cuenta así: retirado del mundo para dedicarse a la devoción, se encariñó con un cervatillo, murió pensando en él y renació como ciervo. La recuerda como advertencia: lo que ocupa la mente en la vida es lo que aparece al morir.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Sea cual sea el estado que uno recuerda cuando al fin deja el cuerpo, a ése mismo va, oh Kaunteya, quedando para siempre conformado por él.", "nota": "<p><em>Sadā</em>, «siempre», puede unirse a lo que precede o a lo que sigue. La traducción principal lo une, como <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, a <em>tad-bhāva-bhāvitaḥ</em>: el que muere recuerda aquello de lo que ha vivido siempre impregnado, y por eso el último pensamiento no se improvisa (de ahí el «en todo momento» del verso siguiente). La alternativa lo lee como el resultado: el que muere queda, desde entonces, hecho de ese estado. <em>Bhāvita</em> admite los dos sentidos: «impregnado, cultivado» y «llevado a ser».</p>"}], "ens": "lo-que-se-recuerda-al-morir"}, {"n": 7, "hablante": "krsna", "sa": ["तस्मात्सर्वेषु कालेषु मामनुस्मर युध्य च ।", "मय्यर्पितमनोबुद्धिर्मामेवैष्यस्यसंशयम् ॥७॥"], "iast": ["tasmāt sarveṣu kāleṣu mām anusmara yudhya ca", "mayy arpita-mano-buddhir mām evaiṣyasy asaṃśayam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Por eso, <a class=\"t\" href=\"glosario.html#smarana\" data-t=\"smarana\">recuérdame</a> en todo momento, y lucha. Con la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> y el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> entregados a mí, vendrás a mí sin duda.</span>", "palabras": [{"iast": "tasmāt", "sa": "तस्मात्", "gram": "abl. sg. pron.", "es": "por eso"}, {"iast": "sarveṣu", "sa": "सर्वेषु", "gram": "loc. pl. m. adj.", "es": "en todos"}, {"iast": "kāleṣu", "sa": "कालेषु", "gram": "loc. pl. m.", "es": "los momentos", "analisis": "kāla (tiempo)"}, {"iast": "mām", "sa": "माम्", "gram": "acc. sg. pron.", "es": "a mí"}, {"iast": "anusmara", "sa": "अनुस्मर", "gram": "2 sg. imperat. act.", "es": "recuerda sin cesar", "ref": "smarana", "analisis": "anu (a lo largo, tras) + √smṛ (recordar)"}, {"iast": "yudhya", "sa": "युध्य", "gram": "2 sg. imperat. act.", "es": "lucha", "analisis": "√yudh (combatir)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "mayi", "sa": "मयि", "gram": "loc. sg. pron.", "es": "en mí"}, {"iast": "arpita-mano-buddhiḥ", "sa": "अर्पितमनोबुद्धिः", "gram": "nom. sg. m. comp.", "es": "con la mente y el entendimiento entregados", "analisis": "arpita (ofrecido, entregado; ppp. caus. de √ṛ) + manas (mente) + buddhi (entendimiento)"}, {"iast": "mām", "sa": "माम्", "gram": "acc. sg. pron.", "es": "a mí"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "sin falta"}, {"iast": "eṣyasi", "sa": "एष्यसि", "gram": "2 sg. fut. act.", "es": "vendrás", "analisis": "√i (ir)"}, {"iast": "asaṃśayam", "sa": "असंशयम्", "gram": "ind.", "es": "sin duda", "ref": "samsaya", "analisis": "a (no) + saṃśaya (duda)"}], "nota": "<p>Si lo que se recuerda al morir es aquello de lo que uno ha vivido impregnado (<a class=\"vref\" href=\"capitulo-08.html#v6\" data-v=\"8.6\">8.6</a>), la única preparación segura para la hora final es recordar a Kṛṣṇa siempre. Pero el verso no dice «retírate a recordarme», sino «recuérdame y lucha»: el recuerdo acompaña a la acción, no la sustituye. Es la misma unión de devoción y deber que pedía <a class=\"vref\" href=\"capitulo-03.html#v30\" data-v=\"3.30\">3.30</a> («entregándome todas las acciones… lucha») y que vuelve en <a class=\"vref\" href=\"capitulo-18.html#v57\" data-v=\"18.57\">18.57</a>.</p>", "interp": [{"titulo": "La devoción no aparta del deber", "html": "<p>En el centro de una enseñanza sobre la muerte y los mundos, el verso devuelve a Arjuna al campo de batalla: su deber de <a class=\"t\" href=\"glosario.html#ksatriya\" data-t=\"ksatriya\">kṣatriya</a> sigue siendo luchar (<a class=\"vref\" href=\"capitulo-02.html#v31\" data-v=\"2.31\">2.31</a>–<a class=\"vref\" href=\"capitulo-02.html#v38\" data-v=\"2.38\">2.38</a>). La novedad del bloque de la devoción es el modo: lo que en los capítulos 2 y 3 era actuar sin apego al fruto, aquí es actuar sin dejar de tener presente a Kṛṣṇa.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "recordar-siempre-y-luchar"}, {"n": 8, "hablante": "krsna", "sa": ["अभ्यासयोगयुक्तेन चेतसा नान्यगामिना ।", "परमं पुरुषं दिव्यं याति पार्थानुचिन्तयन् ॥८॥"], "iast": ["abhyāsa-yoga-yuktena cetasā nānya-gāminā", "paramaṃ puruṣaṃ divyaṃ yāti pārthānucintayan"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Con el pensamiento unido por el yoga de la <a class=\"t\" href=\"glosario.html#abhyasa\" data-t=\"abhyasa\">práctica</a>, sin ir tras ninguna otra cosa, meditando en ella sin cesar, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>, se llega a la <a class=\"t\" href=\"glosario.html#purusa\" data-t=\"purusa\">Persona</a> suprema, divina.</span>", "palabras": [{"iast": "abhyāsa-yoga-yuktena", "sa": "अभ्यासयोगयुक्तेन", "gram": "instr. sg. n. comp.", "es": "unido por el yoga de la práctica", "ref": "abhyasa", "analisis": "abhyāsa (práctica, repetición) + yoga + yukta (unido)"}, {"iast": "cetasā", "sa": "चेतसा", "gram": "instr. sg. n.", "es": "con el pensamiento", "analisis": "cetas (mente, pensamiento)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "anya-gāminā", "sa": "अन्यगामिना", "gram": "instr. sg. n. comp.", "es": "que va a otra cosa", "analisis": "anya (otro) + gāmin (que va)"}, {"iast": "paramam", "sa": "परमम्", "gram": "acc. sg. m. adj.", "es": "suprema"}, {"iast": "puruṣam", "sa": "पुरुषम्", "gram": "acc. sg. m.", "es": "la Persona", "ref": "purusa"}, {"iast": "divyam", "sa": "दिव्यम्", "gram": "acc. sg. m. adj.", "es": "divina"}, {"iast": "yāti", "sa": "याति", "gram": "3 sg. pres. act.", "es": "llega a", "analisis": "√yā (ir)"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha"}, {"iast": "anucintayan", "sa": "अनुचिन्तयन्", "gram": "nom. sg. m. part. pres.", "es": "meditando sin cesar", "analisis": "anu (sin cesar) + √cint (pensar)"}], "nota": "<p><em>Abhyāsa</em>, la práctica repetida, es la que <a class=\"vref\" href=\"capitulo-06.html#v35\" data-v=\"6.35\">6.35</a> daba como remedio para sujetar la mente; aquí se convierte en «yoga». <em>Anucintayan</em>, «pensando sin cesar», y <em>anusmara</em>, «recuerda sin cesar» (<a class=\"vref\" href=\"capitulo-08.html#v7\" data-v=\"8.7\">8.7</a>), llevan el mismo prefijo <em>anu-</em>: no basta un recuerdo ocasional. <em>Paramaṃ puruṣaṃ divyam</em>, «la Persona suprema, divina», es Kṛṣṇa; los versos siguientes la describen.</p>", "interp": [{"titulo": "Una sola idea, repetida", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende la práctica como la repetición de una misma idea, con el pensamiento puesto en el Señor, sin que la interrumpa ninguna idea distinta. Es, con ese añadido, la definición que daba al comentar <a class=\"vref\" href=\"capitulo-06.html#v35\" data-v=\"6.35\">6.35</a>; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> la glosan igual, como un flujo de ideas del mismo tipo.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "partir-con-el-aliento-entre-las-cejas"}, {"n": 9, "hablante": "krsna", "sa": ["कविं पुराणमनुशासितारमणोरणीयांसमनुस्मरेद्यः ।", "सर्वस्य धातारमचिन्त्यरूपमादित्यवर्णं तमसः परस्तात् ॥९॥"], "iast": ["kaviṃ purāṇam anuśāsitāram aṇor aṇīyāṃsam anusmared yaḥ", "sarvasya dhātāram acintya-rūpam āditya-varṇaṃ tamasaḥ parastāt"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Quien recuerda sin cesar al vidente antiguo, al que lo gobierna todo, más sutil que lo más sutil, al que todo lo sostiene, de forma inconcebible, del color del sol, más allá de la oscuridad,</span>", "palabras": [{"iast": "kavim", "sa": "कविम्", "gram": "acc. sg. m.", "es": "al vidente", "analisis": "kavi (sabio inspirado, poeta, vidente)"}, {"iast": "purāṇam", "sa": "पुराणम्", "gram": "acc. sg. m. adj.", "es": "antiguo, primordial"}, {"iast": "anuśāsitāram", "sa": "अनुशासितारम्", "gram": "acc. sg. m.", "es": "al que gobierna", "analisis": "anu-√śās (ordenar, gobernar)"}, {"iast": "aṇoḥ", "sa": "अणोः", "gram": "abl. sg. m.", "es": "que lo diminuto"}, {"iast": "aṇīyāṃsam", "sa": "अणीयांसम्", "gram": "acc. sg. m. comp.", "es": "más sutil", "analisis": "aṇu (diminuto) + -īyas (comparativo)"}, {"iast": "anusmaret", "sa": "अनुस्मरेत्", "gram": "3 sg. opt. act.", "es": "recuerde sin cesar", "ref": "smarana", "analisis": "anu + √smṛ (recordar)"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. pron. rel.", "es": "quien"}, {"iast": "sarvasya", "sa": "सर्वस्य", "gram": "gen. sg. n.", "es": "de todo"}, {"iast": "dhātāram", "sa": "धातारम्", "gram": "acc. sg. m.", "es": "al que sostiene", "analisis": "√dhā (poner, establecer, sostener)"}, {"iast": "acintya-rūpam", "sa": "अचिन्त्यरूपम्", "gram": "acc. sg. m. comp.", "es": "de forma inconcebible", "analisis": "a-cintya (impensable) + rūpa (forma)"}, {"iast": "āditya-varṇam", "sa": "आदित्यवर्णम्", "gram": "acc. sg. m. comp.", "es": "del color del sol", "analisis": "āditya (el sol) + varṇa (color)"}, {"iast": "tamasaḥ", "sa": "तमसः", "gram": "abl. sg. n.", "es": "de la oscuridad", "analisis": "tamas (oscuridad)"}, {"iast": "parastāt", "sa": "परस्तात्", "gram": "ind.", "es": "más allá"}], "nota": "<p>El verso y el siguiente forman una sola frase, en un metro más amplio (<em>triṣṭubh</em>) que el <em>śloka</em> del resto del capítulo, como también <a class=\"vref\" href=\"capitulo-08.html#v11\" data-v=\"8.11\">8.11</a> y <a class=\"vref\" href=\"capitulo-08.html#v28\" data-v=\"8.28\">8.28</a>, como un himno dentro de la enseñanza. Casi todos sus epítetos vienen de las Upaniṣads: véase la interpretación.</p>", "interp": [{"titulo": "Un himno hecho de Upaniṣads", "html": "<p>«Más sutil que lo más sutil» (<em>aṇor aṇīyān</em>) es una fórmula de la <em>Kaṭha Upaniṣad</em> (2.20) y de la <em>Śvetāśvatara</em> (3.20), que la completan con «más grande que lo más grande». «Del color del sol, más allá de la oscuridad» (<em>āditya-varṇaṃ tamasaḥ parastāt</em>) cita casi a la letra la <em>Śvetāśvatara</em> (3.8): «Conozco a esa gran Persona, del color del sol, más allá de la oscuridad; sólo conociéndola se va más allá de la muerte». Y el «vidente» (<em>kavi</em>) que todo lo abarca está ya en la <em>Īśā</em> (8). La Gītā aplica a Kṛṣṇa los nombres que las Upaniṣads daban al principio supremo.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh (cuatro pies de once sílabas)", "alt": [{"html": "Quien recuerda sin cesar al omnisciente, al primordial, al que lo gobierna todo, más sutil que lo más sutil, al que todo lo sostiene, de forma inconcebible, del color del sol, más allá de la oscuridad,", "nota": "<p><em>Kavi</em> es en el Veda el sabio inspirado, el poeta que «ve» lo que otros no ven. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo entienden como «el que ve más allá», es decir, «el que todo lo sabe» (<a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> dicen sólo «omnisciente», <em>sarvajña</em>); y <em>purāṇa</em>, «antiguo», <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y Madhusūdana lo glosan «el que no tiene principio». La traducción principal conserva la imagen del vidente.</p>"}], "ens": "partir-con-el-aliento-entre-las-cejas"}, {"n": 10, "hablante": "krsna", "sa": ["प्रयाणकाले मनसाचलेन भक्त्या युक्तो योगबलेन चैव ।", "भ्रुवोर्मध्ये प्राणमावेश्य सम्यक् स तं परं पुरुषमुपैति दिव्यम् ॥१०॥"], "iast": ["prayāṇa-kāle manasācalena bhaktyā yukto yoga-balena caiva", "bhruvor madhye prāṇam āveśya samyak sa taṃ paraṃ puruṣam upaiti divyam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">en la hora de la partida, con la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> inmóvil, <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unido</a> por la <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">devoción</a> y también por la fuerza del yoga, haciendo entrar por completo el <a class=\"t\" href=\"glosario.html#prana\" data-t=\"prana\">aliento vital</a> entre las cejas, llega a esa <a class=\"t\" href=\"glosario.html#purusa\" data-t=\"purusa\">Persona</a> suprema, divina.</span>", "palabras": [{"iast": "prayāṇa-kāle", "sa": "प्रयाणकाले", "gram": "loc. sg. m. comp.", "es": "en la hora de la partida", "analisis": "prayāṇa (partida; pra-√yā) + kāla (tiempo)"}, {"iast": "manasā", "sa": "मनसा", "gram": "instr. sg. n.", "es": "con la mente", "ref": "manas"}, {"iast": "acalena", "sa": "अचलेन", "gram": "instr. sg. n. adj.", "es": "inmóvil", "analisis": "a (no) + cala (que se mueve)"}, {"iast": "bhaktyā", "sa": "भक्त्या", "gram": "instr. sg. f.", "es": "con devoción", "ref": "bhakti"}, {"iast": "yuktaḥ", "sa": "युक्तः", "gram": "nom. sg. m. ppp.", "es": "unido", "ref": "yukta", "analisis": "√yuj (uncir, unir)"}, {"iast": "yoga-balena", "sa": "योगबलेन", "gram": "instr. sg. n. comp.", "es": "por la fuerza del yoga", "analisis": "yoga + bala (fuerza)"}, {"iast": "ca eva", "sa": "च एव", "gram": "ind.", "es": "y también"}, {"iast": "bhruvoḥ", "sa": "भ्रुवोः", "gram": "gen. du. f.", "es": "de las cejas", "analisis": "bhrū (ceja)"}, {"iast": "madhye", "sa": "मध्ये", "gram": "loc. sg. n.", "es": "en medio"}, {"iast": "prāṇam", "sa": "प्राणम्", "gram": "acc. sg. m.", "es": "el aliento vital", "ref": "prana"}, {"iast": "āveśya", "sa": "आवेश्य", "gram": "ger. caus.", "es": "haciendo entrar", "analisis": "ā-√viś (entrar), causativo"}, {"iast": "samyak", "sa": "सम्यक्", "gram": "ind.", "es": "bien, por completo"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ése"}, {"iast": "tam", "sa": "तम्", "gram": "acc. sg. m. pron.", "es": "a esa"}, {"iast": "param", "sa": "परम्", "gram": "acc. sg. m. adj.", "es": "suprema"}, {"iast": "puruṣam", "sa": "पुरुषम्", "gram": "acc. sg. m.", "es": "Persona", "ref": "purusa"}, {"iast": "upaiti", "sa": "उपैति", "gram": "3 sg. pres. act.", "es": "llega a", "analisis": "upa-√i (acercarse, llegar)"}, {"iast": "divyam", "sa": "दिव्यम्", "gram": "acc. sg. m. adj.", "es": "divina"}], "nota": "<p><em>Prayāṇa-kāla</em>, «la hora de la partida», es la hora de la muerte, como el <em>anta-kāla</em> de <a class=\"vref\" href=\"capitulo-08.html#v5\" data-v=\"8.5\">8.5</a>. <em>Prāṇa</em> va aquí en singular: es el aliento vital, no la pareja <em>prāṇa</em>/<em>apāna</em> de <a class=\"vref\" href=\"capitulo-05.html#v27\" data-v=\"5.27\">5.27</a>. «Entre las cejas» es el lugar donde <a class=\"vref\" href=\"capitulo-05.html#v27\" data-v=\"5.27\">5.27</a> pedía fijar la mirada en la meditación; en <a class=\"vref\" href=\"capitulo-06.html#v13\" data-v=\"6.13\">6.13</a> la mirada se recogía hacia la punta de la nariz. Lo que allí era una postura de la práctica diaria, aquí es el gesto de la hora final. Los versos <a class=\"vref\" href=\"capitulo-08.html#v12\" data-v=\"8.12\">8.12</a>–<a class=\"vref\" href=\"capitulo-08.html#v13\" data-v=\"8.13\">8.13</a> precisan la técnica: cerrar las puertas de los sentidos y llevar el aliento a la cabeza.</p>", "interp": [{"titulo": "Del corazón al entrecejo", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> describe el recorrido (y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo repite, llamando al canal <em>suṣumnā</em>): primero se sujeta el pensamiento en el loto del corazón; luego, por el canal que sube, se eleva el aliento, dominando uno tras otro los elementos, hasta situarlo entre las cejas. Así el yogui llega a la Persona suprema.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Devoción y fuerza de yoga", "html": "<p>El verso reúne dos medios que el libro ha presentado por separado: la devoción (<em>bhaktyā</em>) y la «fuerza del yoga», la que da la práctica del capítulo 6. En la hora de la muerte no se elige entre ellos: se necesitan los dos.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh con pies de jagatī (once y doce sílabas)", "ens": "partir-con-el-aliento-entre-las-cejas"}, {"n": 11, "hablante": "krsna", "sa": ["यदक्षरं वेदविदो वदन्ति विशन्ति यद्यतयो वीतरागाः ।", "यदिच्छन्तो ब्रह्मचर्यं चरन्ति तत्ते पदं संग्रहेण प्रवक्ष्ये ॥११॥"], "iast": ["yad akṣaraṃ veda-vido vadanti viśanti yad yatayo vīta-rāgāḥ", "yad icchanto brahmacaryaṃ caranti tat te padaṃ saṃgraheṇa pravakṣye"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Lo que los conocedores del <a class=\"t\" href=\"glosario.html#veda\" data-t=\"veda\">Veda</a> llaman <a class=\"t\" href=\"glosario.html#aksara\" data-t=\"aksara\">lo imperecedero</a>, aquello en lo que entran los <a class=\"t\" href=\"glosario.html#yati\" data-t=\"yati\">ascetas</a> libres de pasión, aquello por cuyo deseo se practica el <a class=\"t\" href=\"glosario.html#brahmacarya\" data-t=\"brahmacarya\">brahmacarya</a>: esa meta te la expondré en breve.</span>", "palabras": [{"iast": "yat", "sa": "यत्", "gram": "ac. sg. n. rel.", "es": "lo que"}, {"iast": "akṣaram", "sa": "अक्षरम्", "gram": "ac. sg. n.", "es": "lo imperecedero", "ref": "aksara", "analisis": "a (no) + kṣara (que se desgasta, de √kṣar «fluir, perecer»); también «sílaba»"}, {"iast": "veda-vidaḥ", "sa": "वेदविदः", "gram": "nom. pl. m. comp.", "es": "los conocedores del Veda", "ref": "veda", "analisis": "veda + vid (que conoce, de √vid «saber»)"}, {"iast": "vadanti", "sa": "वदन्ति", "gram": "3 pl. pres. act.", "es": "llaman, declaran", "analisis": "√vad (decir)"}, {"iast": "viśanti", "sa": "विशन्ति", "gram": "3 pl. pres. act.", "es": "entran", "analisis": "√viś (entrar)"}, {"iast": "yat", "sa": "यत्", "gram": "ac. sg. n. rel.", "es": "en lo que"}, {"iast": "yatayaḥ", "sa": "यतयः", "gram": "nom. pl. m.", "es": "los ascetas", "ref": "yati", "analisis": "de √yat (esforzarse)"}, {"iast": "vīta-rāgāḥ", "sa": "वीतरागाः", "gram": "nom. pl. m. comp.", "es": "libres de pasión", "ref": "raga-dvesa", "analisis": "vīta (ido, de vi-√i) + rāga (pasión, apego)"}, {"iast": "yat", "sa": "यत्", "gram": "ac. sg. n. rel.", "es": "lo que"}, {"iast": "icchantaḥ", "sa": "इच्छन्तः", "gram": "nom. pl. m. part. pres.", "es": "deseando", "analisis": "√iṣ (desear)"}, {"iast": "brahmacaryam", "sa": "ब्रह्मचर्यम्", "gram": "ac. sg. n.", "es": "el brahmacarya", "ref": "brahmacarya", "analisis": "brahman (el Veda) + carya (conducta)"}, {"iast": "caranti", "sa": "चरन्ति", "gram": "3 pl. pres. act.", "es": "practican", "analisis": "√car (moverse, llevar a cabo)"}, {"iast": "tat", "sa": "तत्", "gram": "ac. sg. n.", "es": "eso"}, {"iast": "te", "sa": "ते", "gram": "dat. sg.", "es": "a ti"}, {"iast": "padam", "sa": "पदम्", "gram": "ac. sg. n.", "es": "meta, estado", "analisis": "«paso, huella; lugar, estado»"}, {"iast": "saṃgraheṇa", "sa": "संग्रहेण", "gram": "instr. sg. m.", "es": "en breve, en resumen", "analisis": "sam + √grah (reunir)"}, {"iast": "pravakṣye", "sa": "प्रवक्ष्ये", "gram": "1 sg. fut. med.", "es": "te diré, expondré", "analisis": "pra + √vac (decir)"}], "nota": "<p>El verso es una cita casi literal de la <a class=\"t\" href=\"glosario.html#katha-upanisad\" data-t=\"katha-upanisad\">Kaṭha Upaniṣad</a> (2.15): «La meta que todos los Vedas proclaman, la que declaran todas las austeridades, aquella por cuyo deseo se practica el <em>brahmacarya</em>, esa meta te la digo en breve: es oṃ». La Gītā cambia la primera mitad, pero conserva la segunda y, como la Upaniṣad, da la respuesta en seguida: oṃ (<a class=\"vref\" href=\"capitulo-08.html#v13\" data-v=\"8.13\">8.13</a>). <em>Akṣara</em>, «lo imperecedero», es la palabra con que Kṛṣṇa ha definido brahman en <a class=\"vref\" href=\"capitulo-08.html#v3\" data-v=\"8.3\">8.3</a>. <em>Padam</em>, «paso, huella», y de ahí «lugar, estado, meta». <em>Vīta-rāga</em>, «aquel de quien se ha ido la pasión», forma parte del compuesto que describe al de sabiduría firme en <a class=\"vref\" href=\"capitulo-02.html#v56\" data-v=\"2.56\">2.56</a> (<em>vīta-rāga-bhaya-krodha</em>, como en <a class=\"vref\" href=\"capitulo-04.html#v10\" data-v=\"4.10\">4.10</a>).</p>", "interp": [{"titulo": "Una cita de la Kaṭha Upaniṣad", "html": "<p>La segunda mitad del verso reproduce la <em>Kaṭha Upaniṣad</em> (2.15) con un solo cambio: <em>pravakṣye</em>, «te diré», en lugar de <em>bravīmi</em>, «te digo». En la Upaniṣad, la Muerte responde así a Naciketas, y la respuesta es «oṃ»; los dos versos siguientes de la Upaniṣad (2.16–2.17) llaman a esa sílaba «brahman imperecedero» y dicen que quien la toma como apoyo es glorificado en el mundo de Brahmā. La Gītā sigue el mismo orden: anuncia la meta, nombra oṃ (<a class=\"vref\" href=\"capitulo-08.html#v13\" data-v=\"8.13\">8.13</a>) y habla luego del mundo de Brahmā (<a class=\"vref\" href=\"capitulo-08.html#v16\" data-v=\"8.16\">8.16</a>), pero para decir que Kṛṣṇa está más allá de él.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh (cuatro pies de once sílabas)", "alt": [{"html": "Lo que los conocedores del Veda llaman la sílaba, aquello en lo que entran los ascetas libres de pasión, aquello por cuyo deseo se practica el brahmacarya: esa meta te la expondré en breve.", "nota": "<p><em>Akṣara</em> significa «imperecedero» y también «sílaba», la unidad de la palabra que no se descompone. La <a class=\"t\" href=\"glosario.html#katha-upanisad\" data-t=\"katha-upanisad\">Kaṭha Upaniṣad</a>, de la que procede la segunda mitad del verso, juega con los dos sentidos: la meta es «oṃ», y «esta sílaba es brahman, esta sílaba es lo supremo» (2.15–2.16). La Gītā recoge ese doble valor dos versos después, cuando llama a oṃ «la sílaba única que es brahman» (<a class=\"vref\" href=\"capitulo-08.html#v13\" data-v=\"8.13\">8.13</a>). La traducción principal toma el primer sentido, el que pide la frase «aquello en lo que entran los ascetas»; esta alternativa hace explícito el segundo, como <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, que entiende aquí «el brahman imperecedero llamado oṃ»; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> toman el primero.</p>"}], "ens": "partir-pronunciando-om"}, {"n": 12, "hablante": "krsna", "sa": ["सर्वद्वाराणि संयम्य मनो हृदि निरुध्य च ।", "मूर्ध्न्याधायात्मनः प्राणमास्थितो योगधारणाम् ॥१२॥"], "iast": ["sarva-dvārāṇi saṃyamya mano hṛdi nirudhya ca", "mūrdhny ādhāyātmanaḥ prāṇam āsthito yoga-dhāraṇām"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Cerrando todas las <a class=\"t\" href=\"glosario.html#nava-dvara\" data-t=\"nava-dvara\">puertas</a>, recogiendo la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> en el corazón, poniendo en la cabeza su <a class=\"t\" href=\"glosario.html#prana\" data-t=\"prana\">aliento vital</a>, establecido en la <a class=\"t\" href=\"glosario.html#dharana\" data-t=\"dharana\">concentración</a> del yoga,</span>", "palabras": [{"iast": "sarva-dvārāṇi", "sa": "सर्वद्वाराणि", "gram": "ac. pl. n. comp.", "es": "todas las puertas", "ref": "nava-dvara", "analisis": "sarva (todo) + dvāra (puerta): las aberturas del cuerpo, por las que entran las percepciones"}, {"iast": "saṃyamya", "sa": "संयम्य", "gram": "ger.", "es": "cerrando, sujetando", "analisis": "sam + √yam (sujetar, refrenar)"}, {"iast": "manaḥ", "sa": "मनः", "gram": "ac. sg. n.", "es": "la mente", "ref": "manas"}, {"iast": "hṛdi", "sa": "हृदि", "gram": "loc. sg. n.", "es": "en el corazón", "analisis": "hṛd (corazón)"}, {"iast": "nirudhya", "sa": "निरुध्य", "gram": "ger.", "es": "recogiendo, conteniendo", "analisis": "ni + √rudh (detener, encerrar)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "mūrdhni", "sa": "मूर्ध्नि", "gram": "loc. sg. m.", "es": "en la cabeza", "analisis": "mūrdhan (cabeza, coronilla)"}, {"iast": "ādhāya", "sa": "आधाय", "gram": "ger.", "es": "poniendo, colocando", "analisis": "ā + √dhā (poner)"}, {"iast": "ātmanaḥ", "sa": "आत्मनः", "gram": "gen. sg. m.", "es": "de uno mismo, su propio"}, {"iast": "prāṇam", "sa": "प्राणम्", "gram": "ac. sg. m.", "es": "el aliento vital", "ref": "prana"}, {"iast": "āsthitaḥ", "sa": "आस्थितः", "gram": "nom. sg. m. part.", "es": "establecido en", "analisis": "ā + √sthā (estar, asentarse)"}, {"iast": "yoga-dhāraṇām", "sa": "योगधारणाम्", "gram": "ac. sg. f. comp.", "es": "la concentración del yoga", "ref": "dharana", "analisis": "yoga + dhāraṇā (sostener, fijar, de √dhṛ)"}], "nota": "<p>El verso describe, en tres pasos, el recogimiento de la hora de la muerte: los sentidos dejan de salir hacia sus objetos, la mente se recoge en el corazón y el aliento vital se lleva a la cabeza. Completa la indicación de <a class=\"vref\" href=\"capitulo-08.html#v10\" data-v=\"8.10\">8.10</a>, donde el aliento se pone «entre las cejas». <em>Dhāraṇā</em>, de √<em>dhṛ</em> «sostener», es la fijación de la mente; la palabra sólo aparece aquí en la Gītā (véase la ficha <a class=\"t\" href=\"glosario.html#dharana\" data-t=\"dharana\">dhāraṇā</a>). La frase continúa en el verso siguiente.</p>", "interp": [{"titulo": "Del corazón a la cabeza", "html": "<p>El camino del corazón a la cabeza tiene un antecedente en la <a class=\"t\" href=\"glosario.html#katha-upanisad\" data-t=\"katha-upanisad\">Kaṭha Upaniṣad</a> (6.16): «Ciento una son las arterias del corazón; de ellas, una sale hacia la coronilla. Subiendo por ella se va a la inmortalidad; las demás sirven para salir en todas direcciones». La Gītā no habla de arterias, pero conserva el movimiento: recoger la mente en el corazón y llevar el aliento a la cabeza.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "El vocabulario del yoga", "html": "<p>Las palabras del verso son las del yoga que los <em>Yoga-sūtra</em> sistematizarán: la sujeción (<em>saṃyama</em>, que en ellos nombrará la unión de fijación, meditación y <em>samādhi</em>, 3.4), la fijación (<em>dhāraṇā</em>) y el aliento (<em>prāṇa</em>). Para Patañjali, <em>dhāraṇā</em> es «la fijación del pensamiento en un lugar» (3.1), el sexto de los ocho miembros del yoga, antes de la meditación (<em>dhyāna</em>) y del <em>samādhi</em>; y el mismo texto menciona el corazón (3.34) y la luz de la cabeza (3.32) como lugares en que se concentra la mente. En la Gītā, en cambio, la técnica sirve a un fin preciso: morir recordando a Kṛṣṇa (<a class=\"vref\" href=\"capitulo-08.html#v13\" data-v=\"8.13\">8.13</a>).</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Sujetando todas las puertas de los sentidos, recogiendo la mente en el corazón, poniendo en la cabeza su aliento vital, establecido en la concentración del yoga,", "nota": "<p><em>Saṃyamya</em> es «sujetando, refrenando», y las «puertas» son las aberturas del cuerpo por las que entra el mundo: los sentidos (las nueve puertas de la ciudad del cuerpo, <a class=\"vref\" href=\"capitulo-05.html#v13\" data-v=\"5.13\">5.13</a>). La traducción principal, «cerrando», da la imagen física, la de las puertas que se cierran; esta alternativa hace explícito, con <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, que lo que se cierra es la actividad de los sentidos, la retirada que los <em>Yoga-sūtra</em> llamarán <em>pratyāhāra</em>. <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, en cambio, piensa en las salidas del cuerpo, que se cierran todas menos la que lleva a la cabeza.</p>"}], "ens": "partir-pronunciando-om"}, {"n": 13, "hablante": "krsna", "sa": ["ओमित्येकाक्षरं ब्रह्म व्याहरन्मामनुस्मरन् ।", "यः प्रयाति त्यजन्देहं स याति परमां गतिम् ॥१३॥"], "iast": ["om ity ekākṣaraṃ brahma vyāharan mām anusmaran", "yaḥ prayāti tyajan dehaṃ sa yāti paramāṃ gatim"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">pronunciando <a class=\"t\" href=\"glosario.html#om\" data-t=\"om\">oṃ</a>, la sílaba única que es <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>, y <a class=\"t\" href=\"glosario.html#smarana\" data-t=\"smarana\">recordándome</a> a mí, quien parte dejando el cuerpo alcanza la meta suprema.</span>", "palabras": [{"iast": "om", "sa": "ओम्", "gram": "ind.", "es": "oṃ", "ref": "om"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "así (cita)"}, {"iast": "ekākṣaram", "sa": "एकाक्षरम्", "gram": "ac. sg. n. comp.", "es": "de una sola sílaba", "ref": "aksara", "analisis": "eka (uno) + akṣara (sílaba; imperecedero)"}, {"iast": "brahma", "sa": "ब्रह्म", "gram": "ac. sg. n.", "es": "brahman", "ref": "brahman"}, {"iast": "vyāharan", "sa": "व्याहरन्", "gram": "nom. sg. m. part. pres.", "es": "pronunciando", "analisis": "vi + ā + √hṛ (pronunciar)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "a mí"}, {"iast": "anusmaran", "sa": "अनुस्मरन्", "gram": "nom. sg. m. part. pres.", "es": "recordando", "ref": "smarana", "analisis": "anu + √smṛ (recordar)"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "quien"}, {"iast": "prayāti", "sa": "प्रयाति", "gram": "3 sg. pres. act.", "es": "parte", "analisis": "pra + √yā (partir; morir)"}, {"iast": "tyajan", "sa": "त्यजन्", "gram": "nom. sg. m. part. pres.", "es": "dejando", "analisis": "√tyaj (abandonar)"}, {"iast": "deham", "sa": "देहम्", "gram": "ac. sg. m.", "es": "el cuerpo"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m.", "es": "él"}, {"iast": "yāti", "sa": "याति", "gram": "3 sg. pres. act.", "es": "va, alcanza", "analisis": "√yā (ir)"}, {"iast": "paramām", "sa": "परमाम्", "gram": "ac. sg. f.", "es": "suprema"}, {"iast": "gatim", "sa": "गतिम्", "gram": "ac. sg. f.", "es": "meta, destino", "analisis": "√gam (ir)"}], "nota": "<p><em>Ekākṣaram brahma</em>: «brahman de una sola sílaba», o «la sílaba única que es brahman». La palabra <em>akṣara</em> reaparece así con su doble sentido: «lo imperecedero» del verso 11 es también «la sílaba» que se pronuncia (véase la alternativa de <a class=\"vref\" href=\"capitulo-08.html#v11\" data-v=\"8.11\">8.11</a>). El verso responde, como la <a class=\"t\" href=\"glosario.html#katha-upanisad\" data-t=\"katha-upanisad\">Kaṭha Upaniṣad</a> (2.15–2.16), con oṃ; pero añade algo que la Upaniṣad no tiene: pronunciar la sílaba y, a la vez, recordar a Kṛṣṇa. <em>Prayāti</em>, «parte», es el verbo de la muerte en todo el capítulo (<a class=\"vref\" href=\"capitulo-08.html#v5\" data-v=\"8.5\">8.5</a>, <a class=\"vref\" href=\"capitulo-08.html#v23\" data-v=\"8.23\">8.23</a>–<a class=\"vref\" href=\"capitulo-08.html#v24\" data-v=\"8.24\">8.24</a>; el sustantivo <em>prayāṇa</em>, en <a class=\"vref\" href=\"capitulo-08.html#v2\" data-v=\"8.2\">8.2</a> y <a class=\"vref\" href=\"capitulo-08.html#v10\" data-v=\"8.10\">8.10</a>).</p>", "interp": [{"titulo": "El nombre y lo nombrado", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende la sílaba como el nombre de brahman: quien muere pronuncia oṃ, el nombre, y recuerda a la vez al Señor, que es su sentido. Lo mismo leen <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>. Antes de <a class=\"vref\" href=\"capitulo-08.html#v12\" data-v=\"8.12\">8.12</a>, Śaṅkara presenta esta meditación en oṃ, nombre o símbolo de brahman, como un medio para los de entendimiento lento o mediano, que libera con el tiempo.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Dos caminos en el mismo capítulo", "html": "<p>Los versos 8.12–8.13 describen una técnica exigente: recogerse, llevar el aliento a la cabeza, pronunciar oṃ en el momento de morir. El verso siguiente ofrece, en cambio, algo que no depende de ese momento: a quien lo recuerda siempre, Kṛṣṇa le es «fácil de alcanzar» (<a class=\"vref\" href=\"capitulo-08.html#v14\" data-v=\"8.14\">8.14</a>). El capítulo pone así, uno junto al otro, el camino del yogui y el del devoto, y el segundo es el que la Gītā desarrollará en los capítulos siguientes.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "partir-pronunciando-om"}, {"n": 14, "hablante": "krsna", "sa": ["अनन्यचेताः सततं यो मां स्मरति नित्यशः ।", "तस्याहं सुलभः पार्थ नित्ययुक्तस्य योगिनः ॥१४॥"], "iast": ["ananya-cetāḥ satataṃ yo māṃ smarati nityaśaḥ", "tasyāhaṃ sulabhaḥ pārtha nitya-yuktasya yoginaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">A quien me <a class=\"t\" href=\"glosario.html#smarana\" data-t=\"smarana\">recuerda</a> sin cesar, siempre, sin pensar en otra cosa, a ese <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yogui</a> siempre <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unido</a> le soy fácil de alcanzar, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>.</span>", "palabras": [{"iast": "ananya-cetāḥ", "sa": "अनन्यचेताः", "gram": "nom. sg. m. comp.", "es": "sin pensar en otra cosa", "analisis": "an-anya (no otro) + cetas (pensamiento)"}, {"iast": "satatam", "sa": "सततम्", "gram": "ind.", "es": "sin cesar"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "quien"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "a mí"}, {"iast": "smarati", "sa": "स्मरति", "gram": "3 sg. pres. act.", "es": "recuerda", "ref": "smarana", "analisis": "√smṛ (recordar)"}, {"iast": "nityaśaḥ", "sa": "नित्यशः", "gram": "ind.", "es": "siempre, cada día"}, {"iast": "tasya", "sa": "तस्य", "gram": "gen. sg. m.", "es": "para él"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg.", "es": "yo"}, {"iast": "sulabhaḥ", "sa": "सुलभः", "gram": "nom. sg. m.", "es": "fácil de alcanzar", "analisis": "su (bien, fácil) + labha (que se obtiene, de √labh)"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha"}, {"iast": "nitya-yuktasya", "sa": "नित्ययुक्तस्य", "gram": "gen. sg. m. comp.", "es": "siempre unido", "ref": "yukta", "analisis": "nitya (siempre) + yukta (unido)"}, {"iast": "yoginaḥ", "sa": "योगिनः", "gram": "gen. sg. m.", "es": "del yogui", "ref": "yogin"}], "nota": "<p><em>Satatam</em> y <em>nityaśaḥ</em> dicen casi lo mismo, «sin cesar» y «siempre», y su acumulación es enfática: no se trata de recordar a Kṛṣṇa en la hora de la muerte, sino a lo largo de la vida, para que en esa hora el recuerdo venga solo (<a class=\"vref\" href=\"capitulo-08.html#v6\" data-v=\"8.6\">8.6</a>–<a class=\"vref\" href=\"capitulo-08.html#v7\" data-v=\"8.7\">8.7</a>). <em>Ananya-cetāḥ</em>, «cuyo pensamiento no es de otro», anticipa la «devoción sin otro objeto» (<em>ananya-bhakti</em>) de <a class=\"vref\" href=\"capitulo-08.html#v22\" data-v=\"8.22\">8.22</a> y <a class=\"vref\" href=\"capitulo-09.html#v22\" data-v=\"9.22\">9.22</a>. <em>Sulabha</em>, «fácil de obtener», contrasta con lo que el capítulo 7 decía del sabio, «muy difícil de encontrar» (<em>sudurlabha</em>, <a class=\"vref\" href=\"capitulo-07.html#v19\" data-v=\"7.19\">7.19</a>).</p>", "interp": [{"titulo": "Toda la vida", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> distingue las dos palabras: <em>satatam</em> es la continuidad, sin interrupción, y <em>nityaśaḥ</em> la duración, no seis meses o un año, sino mientras dura la vida. Lo sigue <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, que ve aquí la práctica firme de los <em>Yoga-sūtra</em> (1.14); para <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, <em>nityaśaḥ</em> es «cada día».</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "El tercer aspirante", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lee el capítulo según las clases de aspirantes que han aparecido al final del 7 (<a class=\"vref\" href=\"capitulo-07.html#v29\" data-v=\"7.29\">7.29</a>–<a class=\"vref\" href=\"capitulo-07.html#v30\" data-v=\"7.30\">7.30</a>): el que busca poder y prosperidad, el que busca la visión de su propio sí-mismo y el sabio que busca a Kṛṣṇa mismo. Este verso, en su lectura, describe al tercero: el que no puede sostenerse sin recordarlo, y para quien Kṛṣṇa se hace fácil de alcanzar.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "facil-de-alcanzar"}, {"n": 15, "hablante": "krsna", "sa": ["मामुपेत्य पुनर्जन्म दुःखालयमशाश्वतम् ।", "नाप्नुवन्ति महात्मानः संसिद्धिं परमां गताः ॥१५॥"], "iast": ["mām upetya punar-janma duḥkhālayam aśāśvatam", "nāpnuvanti mahātmānaḥ saṃsiddhiṃ paramāṃ gatāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Llegados a mí, los <a class=\"t\" href=\"glosario.html#mahatman\" data-t=\"mahatman\">grandes seres</a> que han alcanzado la perfección suprema no tienen ya otro nacimiento, esa morada del <a class=\"t\" href=\"glosario.html#duhkha\" data-t=\"duhkha\">dolor</a>, pasajera.</span>", "palabras": [{"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "a mí"}, {"iast": "upetya", "sa": "उपेत्य", "gram": "ger.", "es": "llegando a", "analisis": "upa + √i (ir hacia)"}, {"iast": "punar-janma", "sa": "पुनर्जन्म", "gram": "ac. sg. n. comp.", "es": "otro nacimiento", "ref": "samsara", "analisis": "punar (de nuevo) + janman (nacimiento)"}, {"iast": "duḥkhālayam", "sa": "दुःखालयम्", "gram": "ac. sg. n. comp.", "es": "morada del dolor", "ref": "duhkha", "analisis": "duḥkha (dolor) + ālaya (morada)"}, {"iast": "aśāśvatam", "sa": "अशाश्वतम्", "gram": "ac. sg. n.", "es": "pasajero", "analisis": "a (no) + śāśvata (perpetuo)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "āpnuvanti", "sa": "आप्नुवन्ति", "gram": "3 pl. pres. act.", "es": "obtienen", "analisis": "√āp (alcanzar)"}, {"iast": "mahātmānaḥ", "sa": "महात्मानः", "gram": "nom. pl. m.", "es": "los grandes seres", "ref": "mahatman", "analisis": "mahat (grande) + ātman"}, {"iast": "saṃsiddhim", "sa": "संसिद्धिम्", "gram": "ac. sg. f.", "es": "la perfección", "analisis": "sam + √sidh (cumplirse)"}, {"iast": "paramām", "sa": "परमाम्", "gram": "ac. sg. f.", "es": "suprema"}, {"iast": "gatāḥ", "sa": "गताः", "gram": "nom. pl. m. part.", "es": "que han alcanzado", "analisis": "√gam (ir)"}], "nota": "<p>Lo que se llama «morada del dolor, pasajera» (<em>duḥkhālayam aśāśvatam</em>) no es el mundo, sino el nuevo nacimiento (<em>punar-janma</em>), con el que concuerdan los dos adjetivos. El juicio sobre el mundo es parecido, pero llega más adelante: «este mundo, pasajero y sin dicha» (<a class=\"vref\" href=\"capitulo-09.html#v33\" data-v=\"9.33\">9.33</a>). <em>Mahātman</em>, «gran ser», es el nombre que <a class=\"vref\" href=\"capitulo-07.html#v19\" data-v=\"7.19\">7.19</a> daba al sabio que se refugia en Kṛṣṇa.</p>", "interp": [{"titulo": "La salida del ciclo", "html": "<p>En <a class=\"vref\" href=\"capitulo-04.html#v9\" data-v=\"4.9\">4.9</a> Kṛṣṇa había prometido lo mismo a quien conoce su nacimiento y su obra divinos: «dejando el cuerpo, no vuelve a nacer; viene a mí». Los dos versos usan la misma palabra, <em>punar-janma</em>, y la oponen a «venir a mí»: el ciclo de los nacimientos (<a class=\"t\" href=\"glosario.html#samsara\" data-t=\"samsara\">saṃsāra</a>) no termina en la nada, sino en Kṛṣṇa.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "facil-de-alcanzar"}, {"n": 16, "hablante": "krsna", "sa": ["आब्रह्मभुवनाल्लोकाः पुनरावर्तिनोऽर्जुन ।", "मामुपेत्य तु कौन्तेय पुनर्जन्म न विद्यते ॥१६॥"], "iast": ["ā-brahma-bhuvanāl lokāḥ punar āvartino 'rjuna", "mām upetya tu kaunteya punar-janma na vidyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Los mundos, <a class=\"t\" href=\"glosario.html#brahmaloka\" data-t=\"brahmaloka\">hasta el de Brahmā</a>, están sujetos a volver, oh <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>; pero quien llega a mí, oh <a class=\"t\" href=\"glosario.html#kaunteya\" data-t=\"kaunteya\">Kaunteya</a>, no vuelve a nacer.</span>", "palabras": [{"iast": "ā-brahma-bhuvanāt", "sa": "आब्रह्मभुवनात्", "gram": "abl. sg. n. comp.", "es": "hasta el mundo de Brahmā", "ref": "brahmaloka", "analisis": "ā (hasta) + brahma (Brahmā) + bhuvana (mundo, morada)"}, {"iast": "lokāḥ", "sa": "लोकाः", "gram": "nom. pl. m.", "es": "los mundos"}, {"iast": "punar", "sa": "पुनर्", "gram": "ind.", "es": "de nuevo"}, {"iast": "āvartinaḥ", "sa": "आवर्तिनः", "gram": "nom. pl. m.", "es": "sujetos al retorno", "analisis": "ā + √vṛt (volver)"}, {"iast": "arjuna", "sa": "अर्जुन", "gram": "voc. sg. m.", "es": "oh Arjuna", "ref": "arjuna"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg.", "es": "a mí"}, {"iast": "upetya", "sa": "उपेत्य", "gram": "ger.", "es": "llegando a", "analisis": "upa + √i (ir hacia)"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "kaunteya", "sa": "कौन्तेय", "gram": "voc. sg. m.", "es": "oh Kaunteya", "ref": "kaunteya"}, {"iast": "punar-janma", "sa": "पुनर्जन्म", "gram": "nom. sg. n. comp.", "es": "otro nacimiento", "analisis": "punar (de nuevo) + janman (nacimiento)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "vidyate", "sa": "विद्यते", "gram": "3 sg. pres. pas.", "es": "hay, existe", "analisis": "√vid (encontrarse, existir)"}], "nota": "<p><em>Ā-brahma-bhuvanāt</em>: «hasta la morada de Brahmā», el dios creador (<a class=\"t\" href=\"glosario.html#brahma-deva\" data-t=\"brahma-deva\">Brahmā</a>), no brahman. La preposición <em>ā</em> puede incluir el término («hasta él inclusive») o excluirlo («hasta él, sin contarlo»); la traducción toma el primer sentido, que confirman los versos siguientes: también el día de Brahmā tiene fin (<a class=\"vref\" href=\"capitulo-08.html#v17\" data-v=\"8.17\">8.17</a>–<a class=\"vref\" href=\"capitulo-08.html#v19\" data-v=\"8.19\">8.19</a>). Así lo leen <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> («junto con el mundo de Brahmā»), <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, que lo llama expresamente <em>abhividhi</em>, «inclusión»; <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, en cambio, toma el sentido excluyente: vuelven los mundos que están por debajo de la morada de Brahmā, que sitúa en el monte Meru. Lo que «vuelve» no son los mundos mismos, sino quienes los alcanzan: agotado el mérito que los llevó allí, vuelven a nacer, como dirá <a class=\"vref\" href=\"capitulo-09.html#v21\" data-v=\"9.21\">9.21</a>.</p>", "interp": [{"titulo": "¿Se vuelve también del mundo de Brahmā?", "html": "<p>Las <a class=\"t\" href=\"glosario.html#upanisad\" data-t=\"upanisad\">Upaniṣads</a> hacen a veces del mundo de Brahmā la meta del camino de los dioses, de la que no se vuelve; el verso parece contradecirlas. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> concilian las dos cosas con la doctrina de la liberación gradual (<em>krama-mukti</em>), en la línea de los <em>Brahma-sūtra</em> (4.3.10): quienes llegan al mundo de Brahmā por las meditaciones que llevan a ese fin alcanzan allí el conocimiento y se liberan con Brahmā al final de la vida de éste; los demás, los que llegan por las obras, vuelven. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> no recurre a ella: los que alcanzan esos mundos buscando el poder vuelven porque los mundos mismos perecen. El verso, en cambio, no distingue: pone todos los mundos de un lado y a Kṛṣṇa del otro.</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "facil-de-alcanzar"}, {"n": 17, "hablante": "krsna", "sa": ["सहस्रयुगपर्यन्तमहर्यद्ब्रह्मणो विदुः ।", "रात्रिं युगसहस्रान्तां तेऽहोरात्रविदो जनाः ॥१७॥"], "iast": ["sahasra-yuga-paryantam ahar yad brahmaṇo viduḥ", "rātriṃ yuga-sahasrāntāṃ te 'ho-rātra-vido janāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Los que saben que el día de <a class=\"t\" href=\"glosario.html#brahma-deva\" data-t=\"brahma-deva\">Brahmā</a> dura mil <a class=\"t\" href=\"glosario.html#yuga\" data-t=\"yuga\">eras</a>, y que su noche termina al cabo de otras mil, ésos son los que conocen el día y la noche.</span>", "palabras": [{"iast": "sahasra-yuga-paryantam", "sa": "सहस्रयुगपर्यन्तम्", "gram": "ac. sg. n. comp.", "es": "que dura mil eras", "ref": "yuga", "analisis": "sahasra (mil) + yuga (era) + paryanta (término): «que tiene por término mil eras»"}, {"iast": "ahar", "sa": "अहर्", "gram": "ac. sg. n.", "es": "día", "analisis": "ahan (día); ahar, forma ante sonora"}, {"iast": "yad", "sa": "यद्", "gram": "ac. sg. n. rel.", "es": "que"}, {"iast": "brahmaṇaḥ", "sa": "ब्रह्मणः", "gram": "gen. sg. m.", "es": "de Brahmā", "ref": "brahma-deva", "analisis": "brahman (masc., el dios Brahmā); el genitivo del neutro brahman tiene la misma forma"}, {"iast": "viduḥ", "sa": "विदुः", "gram": "3 pl. pf. act.", "es": "saben", "analisis": "√vid (saber); perfecto con valor de presente"}, {"iast": "rātrim", "sa": "रात्रिम्", "gram": "ac. sg. f.", "es": "la noche"}, {"iast": "yuga-sahasrāntām", "sa": "युगसहस्रान्ताम्", "gram": "ac. sg. f. comp.", "es": "que termina al cabo de mil eras", "ref": "yuga", "analisis": "yuga (era) + sahasra (mil) + anta (fin)"}, {"iast": "te", "sa": "ते", "gram": "nom. pl. m. pron.", "es": "ésos"}, {"iast": "aho-rātra-vidaḥ", "sa": "अहोरात्रविदः", "gram": "nom. pl. m. comp.", "es": "los que conocen el día y la noche", "analisis": "ahan (día) + rātri (noche) + vid (que conoce)"}, {"iast": "janāḥ", "sa": "जनाः", "gram": "nom. pl. m.", "es": "las personas, los hombres", "analisis": "√jan (nacer)"}], "nota": "<p><em>Brahmaṇaḥ</em> es a la vez genitivo de <em>brahman</em>, neutro, lo absoluto, y de <em>Brahmā</em>, masculino, el dios creador. Aquí se trata del dios: el verso explica por qué de los mundos, «hasta el de Brahmā», se vuelve (<a class=\"vref\" href=\"capitulo-08.html#v16\" data-v=\"8.16\">8.16</a>): también el creador vive en el tiempo. Las <em>Leyes de Manu</em> (1.73) traen un verso casi idéntico. Un día de Brahmā es un <a class=\"t\" href=\"glosario.html#kalpa\" data-t=\"kalpa\">kalpa</a>; la palabra aparece en <a class=\"vref\" href=\"capitulo-09.html#v7\" data-v=\"9.7\">9.7</a>.</p>", "interp": [{"titulo": "La medida del tiempo", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> enlaza el verso con el anterior: los mundos, hasta el de Brahmā, están limitados por el tiempo, y por eso se vuelve de ellos. «Los que conocen el día y la noche» son, para él, los que conocen la medida del tiempo, y <em>brahmaṇaḥ</em> designa a Prajāpati, el creador. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> comparte el enlace y la glosa de <em>brahmaṇaḥ</em>, pero él y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> entienden que sólo los yoguis conocen de verdad ese día y esa noche, no quienes los cuentan por el curso del sol y de la luna.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La cuenta de los Purāṇas", "html": "<p>El verso no da cifras, pero la tradición purāṇica las hace explícitas, y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> las recoge en su comentario citando el <em>Viṣṇu Purāṇa</em>. Según el <em>Viṣṇu Purāṇa</em> (1.3), un año de los hombres es un día y una noche de los dioses (el curso norte del sol es su día; el sur, su noche); doce mil años de los dioses forman un ciclo de cuatro eras; mil ciclos, un día de Brahmā, y otros mil, su noche. En años humanos, un día de Brahmā suma unos 4.320 millones. Brahmā vive cien años hechos de esos días y noches.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Los que saben que el día de Brahmā abarca mil grandes ciclos de cuatro eras, y su noche otros mil, ésos son los que conocen el día y la noche.", "nota": "<p><em>Yuga</em> puede designar cada una de las cuatro edades del mundo o el ciclo entero que forman (<em>mahā-yuga</em> o <em>catur-yuga</em>). La cuenta tradicional, y con ella <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, entiende aquí el segundo: las <em>Leyes de Manu</em> llaman «era de los dioses» a un ciclo de cuatro edades (1.71) y cuentan mil de ellas para un día de Brahmā (1.72); véanse las fichas <a class=\"t\" href=\"glosario.html#yuga\" data-t=\"yuga\">yuga</a> y <a class=\"t\" href=\"glosario.html#kalpa\" data-t=\"kalpa\">kalpa</a>. La traducción principal deja la palabra del texto, «eras».</p>"}], "ens": "el-dia-y-la-noche-de-brahma"}, {"n": 18, "hablante": "krsna", "sa": ["अव्यक्ताद्व्यक्तयः सर्वाः प्रभवन्त्यहरागमे ।", "रात्र्यागमे प्रलीयन्ते तत्रैवाव्यक्तसंज्ञके ॥१८॥"], "iast": ["avyaktād vyaktayaḥ sarvāḥ prabhavanty ahar-āgame", "rātry-āgame pralīyante tatraivāvyakta-saṃjñake"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Al llegar el día, todo lo manifiesto surge de lo <a class=\"t\" href=\"glosario.html#avyakta\" data-t=\"avyakta\">no manifiesto</a>; al llegar la noche, se <a class=\"t\" href=\"glosario.html#pralaya\" data-t=\"pralaya\">disuelve</a> en eso mismo que se llama lo no manifiesto.</span>", "palabras": [{"iast": "avyaktāt", "sa": "अव्यक्तात्", "gram": "abl. sg. n.", "es": "de lo no manifiesto", "ref": "avyakta", "analisis": "a (no) + vyakta (manifiesto)"}, {"iast": "vyaktayaḥ", "sa": "व्यक्तयः", "gram": "nom. pl. f.", "es": "las manifestaciones, lo manifiesto", "analisis": "vi-√añj (manifestar)"}, {"iast": "sarvāḥ", "sa": "सर्वाः", "gram": "nom. pl. f.", "es": "todas"}, {"iast": "prabhavanti", "sa": "प्रभवन्ति", "gram": "3 pl. pres. act.", "es": "surgen", "analisis": "pra + √bhū (llegar a ser)"}, {"iast": "ahar-āgame", "sa": "अहरागमे", "gram": "loc. sg. m. comp.", "es": "al llegar el día", "analisis": "ahan (día) + āgama (llegada)"}, {"iast": "rātri-āgame", "sa": "रात्र्यागमे", "gram": "loc. sg. m. comp.", "es": "al llegar la noche", "analisis": "rātri (noche) + āgama (llegada)"}, {"iast": "pralīyante", "sa": "प्रलीयन्ते", "gram": "3 pl. pres. med.", "es": "se disuelven", "ref": "pralaya", "analisis": "pra + √lī (disolverse, fundirse)"}, {"iast": "tatra", "sa": "तत्र", "gram": "ind.", "es": "allí, en eso"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "mismo"}, {"iast": "avyakta-saṃjñake", "sa": "अव्यक्तसंज्ञके", "gram": "loc. sg. n. comp.", "es": "en lo que se llama no manifiesto", "ref": "avyakta", "analisis": "avyakta (no manifiesto) + saṃjñaka (que tiene por nombre)"}], "nota": "<p><em>Vyaktayaḥ</em>, «las manifestaciones»: todo lo que tiene forma perceptible, seres y cosas. Lo no manifiesto puede entenderse aquí como la naturaleza en reposo, sin desplegar, de la que todo surge y en la que todo se reabsorbe (véase la ficha <a class=\"t\" href=\"glosario.html#avyakta\" data-t=\"avyakta\">avyakta</a>); <a class=\"vref\" href=\"capitulo-08.html#v20\" data-v=\"8.20\">8.20</a> hablará de otro no manifiesto, superior. Es la disolución que llega al final de cada día de Brahmā (<a class=\"t\" href=\"glosario.html#pralaya\" data-t=\"pralaya\">pralaya</a>).</p>", "interp": [{"titulo": "El sueño del creador", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, y con él <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, entiende que lo no manifiesto de este verso es el estado de sueño de Prajāpati, el creador: al despertar, al comenzar su día, todo surge de él; al dormirse, todo vuelve a él.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La naturaleza que se despliega y se recoge", "html": "<p>En <a class=\"vref\" href=\"capitulo-09.html#v7\" data-v=\"9.7\">9.7</a>–<a class=\"vref\" href=\"capitulo-09.html#v8\" data-v=\"9.8\">9.8</a> Kṛṣṇa dirá lo mismo en primera persona: al acabarse un kalpa, todos los seres entran en su naturaleza, y al comienzo de otro él los emite de nuevo. El ciclo cósmico no es un mecanismo independiente: es la naturaleza de Kṛṣṇa la que se despliega y se recoge.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-dia-y-la-noche-de-brahma"}, {"n": 19, "hablante": "krsna", "sa": ["भूतग्रामः स एवायं भूत्वा भूत्वा प्रलीयते ।", "रात्र्यागमेऽवशः पार्थ प्रभवत्यहरागमे ॥१९॥"], "iast": ["bhūta-grāmaḥ sa evāyaṃ bhūtvā bhūtvā pralīyate", "rātry-āgame 'vaśaḥ pārtha prabhavaty ahar-āgame"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Esta misma multitud de seres, que llega a ser una y otra vez, se disuelve sin poder evitarlo al llegar la noche, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>, y vuelve a surgir al llegar el día.</span>", "palabras": [{"iast": "bhūta-grāmaḥ", "sa": "भूतग्रामः", "gram": "nom. sg. m. comp.", "es": "la multitud de los seres", "analisis": "bhūta (ser) + grāma (conjunto; literalmente, aldea)"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ese"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "mismo"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m. pron.", "es": "este"}, {"iast": "bhūtvā bhūtvā", "sa": "भूत्वा भूत्वा", "gram": "abs.", "es": "llegando a ser una y otra vez", "analisis": "√bhū (llegar a ser); la repetición expresa reiteración"}, {"iast": "pralīyate", "sa": "प्रलीयते", "gram": "3 sg. pres. med.", "es": "se disuelve", "ref": "pralaya", "analisis": "pra + √lī (disolverse)"}, {"iast": "rātri-āgame", "sa": "रात्र्यागमे", "gram": "loc. sg. m. comp.", "es": "al llegar la noche", "analisis": "rātri (noche) + āgama (llegada)"}, {"iast": "avaśaḥ", "sa": "अवशः", "gram": "nom. sg. m. adj.", "es": "sin poder evitarlo, a su pesar", "analisis": "a (sin) + vaśa (dominio, voluntad)"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha"}, {"iast": "prabhavati", "sa": "प्रभवति", "gram": "3 sg. pres. act.", "es": "surge", "analisis": "pra + √bhū (llegar a ser)"}, {"iast": "ahar-āgame", "sa": "अहरागमे", "gram": "loc. sg. m. comp.", "es": "al llegar el día", "analisis": "ahan (día) + āgama (llegada)"}], "nota": "<p><em>Bhūta-grāma</em>, «la multitud de los seres» (<em>grāma</em> es, literalmente, «aldea»). <em>Bhūtvā bhūtvā</em>, «llegando a ser, llegando a ser»: la repetición expresa la vuelta incesante. <em>Sa evāyam</em>, «esta misma»: no surgen otros seres, sino los mismos. <em>Avaśa</em>, «sin dominio», «a su pesar»: los seres no deciden ni su disolución ni su regreso; <a class=\"vref\" href=\"capitulo-09.html#v8\" data-v=\"9.8\">9.8</a> dirá que Kṛṣṇa emite una y otra vez la multitud de los seres, «sin poder propio, por el poder de la naturaleza» (<em>avaśaṃ prakṛter vaśāt</em>).</p>", "interp": [{"titulo": "Los mismos, no otros", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, como <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, explica por qué el verso insiste en que es «esta misma» multitud la que vuelve: si en cada día surgieran seres nuevos, unos recibirían frutos de acciones que no hicieron y otros perderían los de las que hicieron. Y lo dice para que nazca el desapego: nadie, en el ciclo, es dueño de su suerte. <em>Avaśa</em>, «sin poder evitarlo», es para él «por la fuerza de las acciones» pasadas.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-dia-y-la-noche-de-brahma"}, {"n": 20, "hablante": "krsna", "sa": ["परस्तस्मात्तु भावोऽन्योऽव्यक्तोऽव्यक्तात्सनातनः ।", "यः स सर्वेषु भूतेषु नश्यत्सु न विनश्यति ॥२०॥"], "iast": ["paras tasmāt tu bhāvo 'nyo 'vyakto 'vyaktāt sanātanaḥ", "yaḥ sa sarveṣu bhūteṣu naśyatsu na vinaśyati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pero más allá de ese no manifiesto hay otra realidad, no manifiesta y eterna, que no perece cuando perecen todos los seres.</span>", "palabras": [{"iast": "paraḥ", "sa": "परः", "gram": "nom. sg. m. adj.", "es": "superior, más allá"}, {"iast": "tasmāt", "sa": "तस्मात्", "gram": "abl. sg. pron.", "es": "que aquél"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "bhāvaḥ", "sa": "भावः", "gram": "nom. sg. m.", "es": "realidad, modo de ser", "analisis": "√bhū (ser)"}, {"iast": "anyaḥ", "sa": "अन्यः", "gram": "nom. sg. m. pron.", "es": "otro, distinto"}, {"iast": "avyaktaḥ", "sa": "अव्यक्तः", "gram": "nom. sg. m.", "es": "no manifiesto", "ref": "avyakta", "analisis": "a (no) + vyakta (manifiesto)"}, {"iast": "avyaktāt", "sa": "अव्यक्तात्", "gram": "abl. sg. n.", "es": "que lo no manifiesto", "ref": "avyakta"}, {"iast": "sanātanaḥ", "sa": "सनातनः", "gram": "nom. sg. m. adj.", "es": "eterno", "analisis": "sanā (siempre)"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "que"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ése"}, {"iast": "sarveṣu", "sa": "सर्वेषु", "gram": "loc. pl. n.", "es": "todos"}, {"iast": "bhūteṣu", "sa": "भूतेषु", "gram": "loc. pl. n.", "es": "los seres"}, {"iast": "naśyatsu", "sa": "नश्यत्सु", "gram": "loc. pl. n. part. pres.", "es": "al perecer", "analisis": "√naś (perecer); locativo absoluto: «cuando perecen»"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "vinaśyati", "sa": "विनश्यति", "gram": "3 sg. pres. act.", "es": "perece", "analisis": "vi + √naś (perecer)"}], "nota": "<p>Hay, pues, dos «no manifiestos»: el de <a class=\"vref\" href=\"capitulo-08.html#v18\" data-v=\"8.18\">8.18</a>, la naturaleza en reposo, de la que los seres surgen y en la que se disuelven, y éste, «otro» (<em>anya</em>) y superior (<em>para</em>), que no está sometido al ciclo. <em>Bhāva</em>, de √bhū «ser», es «lo que es»: una realidad, un modo de ser. <em>Naśyatsu</em> es un locativo absoluto: «cuando perecen», «aunque perezcan». Lo que no perece cuando todo perece recuerda lo que dice <a class=\"vref\" href=\"capitulo-02.html#v17\" data-v=\"2.17\">2.17</a>–<a class=\"vref\" href=\"capitulo-02.html#v18\" data-v=\"2.18\">2.18</a> del que habita el cuerpo.</p>", "interp": [{"titulo": "Lo imperecedero, de otra naturaleza", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende esta otra realidad como el brahman imperecedero, de naturaleza distinta de lo no manifiesto que es semilla de los seres: no es una forma más sutil de la naturaleza, sino lo que está fuera del ciclo. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo entienden de modo semejante, como el Señor supremo (<em>parameśvara</em>), causa de aquel no manifiesto.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "El sí-mismo libre de la naturaleza", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lee los versos <a class=\"vref\" href=\"capitulo-08.html#v20\" data-v=\"8.20\">8.20</a>–<a class=\"vref\" href=\"capitulo-08.html#v21\" data-v=\"8.21\">8.21</a> dentro del esquema de las tres clases de aspirantes que, según él, ordena el capítulo: lo no manifiesto superior y lo imperecedero son aquí el sí-mismo individual en su pureza, distinto de la naturaleza inconsciente, que es la meta del que busca el aislamiento (<em>kaivalya</em>); la Persona suprema de <a class=\"vref\" href=\"capitulo-08.html#v22\" data-v=\"8.22\">8.22</a>, a la que se llega por la devoción, es otra meta, más alta.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "lo-no-manifiesto-eterno"}, {"n": 21, "hablante": "krsna", "sa": ["अव्यक्तोऽक्षर इत्युक्तस्तमाहुः परमां गतिम् ।", "यं प्राप्य न निवर्तन्ते तद्धाम परमं मम ॥२१॥"], "iast": ["avyakto 'kṣara ity uktas tam āhuḥ paramāṃ gatim", "yaṃ prāpya na nivartante tad dhāma paramaṃ mama"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">A ese no manifiesto se lo llama lo <a class=\"t\" href=\"glosario.html#aksara\" data-t=\"aksara\">imperecedero</a>, y dicen que es la meta suprema: los que lo alcanzan ya no vuelven. Ésa es mi morada suprema.</span>", "palabras": [{"iast": "avyaktaḥ", "sa": "अव्यक्तः", "gram": "nom. sg. m.", "es": "no manifiesto", "ref": "avyakta"}, {"iast": "akṣaraḥ", "sa": "अक्षरः", "gram": "nom. sg. m.", "es": "imperecedero", "ref": "aksara", "analisis": "a (no) + √kṣar (fluir, desgastarse)"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "así (cita)"}, {"iast": "uktaḥ", "sa": "उक्तः", "gram": "nom. sg. m. ppp", "es": "llamado, dicho", "analisis": "√vac (decir)"}, {"iast": "tam", "sa": "तम्", "gram": "ac. sg. m. pron.", "es": "a él"}, {"iast": "āhuḥ", "sa": "आहुः", "gram": "3 pl. pf. act.", "es": "dicen, llaman", "analisis": "√ah (decir)"}, {"iast": "paramām", "sa": "परमाम्", "gram": "ac. sg. f. adj.", "es": "suprema"}, {"iast": "gatim", "sa": "गतिम्", "gram": "ac. sg. f.", "es": "meta, destino", "analisis": "√gam (ir)"}, {"iast": "yam", "sa": "यम्", "gram": "ac. sg. m. rel.", "es": "al cual"}, {"iast": "prāpya", "sa": "प्राप्य", "gram": "abs.", "es": "una vez alcanzado", "analisis": "pra + √āp (alcanzar)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "nivartante", "sa": "निवर्तन्ते", "gram": "3 pl. pres. med.", "es": "vuelven", "analisis": "ni + √vṛt (volverse)"}, {"iast": "tat", "sa": "तत्", "gram": "nom. sg. n. pron.", "es": "eso"}, {"iast": "dhāma", "sa": "धाम", "gram": "nom. sg. n.", "es": "morada; estado; esplendor", "analisis": "dhāman, de √dhā (poner, establecer)"}, {"iast": "paramam", "sa": "परमम्", "gram": "nom. sg. n. adj.", "es": "supremo"}, {"iast": "mama", "sa": "मम", "gram": "gen. sg. pron.", "es": "mi"}], "nota": "<p><em>Akṣara</em>, «imperecedero», es la palabra con que Kṛṣṇa ha definido brahman en <a class=\"vref\" href=\"capitulo-08.html#v3\" data-v=\"8.3\">8.3</a> («brahman es lo imperecedero supremo»). La fórmula de la segunda mitad, «sin retorno», volverá casi igual en <a class=\"vref\" href=\"capitulo-15.html#v6\" data-v=\"15.6\">15.6</a>: «aquello a lo que se va y de donde no se vuelve, ésa es mi morada suprema».</p>", "interp": [{"titulo": "La meta de la que no se vuelve", "html": "<p>El verso cierra el contraste abierto en <a class=\"vref\" href=\"capitulo-08.html#v16\" data-v=\"8.16\">8.16</a>: de todos los mundos se vuelve, incluso del de Brahmā; de esto, no. Lo que el capítulo llama la «meta suprema» se define por su diferencia con todo lo que pertenece al ciclo: no tiene día ni noche, no surge ni se disuelve.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "A ese no manifiesto se lo llama lo imperecedero, y dicen que es la meta suprema: los que lo alcanzan ya no vuelven. Ése es mi estado supremo.", "nota": "<p><em>Dhāman</em> significa «morada, sede», pero también «estado, condición» y «luz, esplendor». La traducción principal toma el primer sentido, que es el más corriente; la alternativa, el segundo, que no hace pensar en un lugar. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo glosa como «lugar» (<em>sthāna</em>) y lo identifica con el <em>paramaṃ padam</em> de Viṣṇu; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, como «naturaleza propia» (<em>svarūpa</em>); <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, como su naturaleza luminosa; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, como el más alto de los ámbitos que Kṛṣṇa gobierna, el sí-mismo liberado; Prabhupāda, en la tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a>, traduce «My supreme abode» y la identifica con Goloka Vṛndāvana, el planeta más alto del reino espiritual.</p>"}], "ens": "lo-no-manifiesto-eterno"}, {"n": 22, "hablante": "krsna", "sa": ["पुरुषः स परः पार्थ भक्त्या लभ्यस्त्वनन्यया ।", "यस्यान्तःस्थानि भूतानि येन सर्वमिदं ततम् ॥२२॥"], "iast": ["puruṣaḥ sa paraḥ pārtha bhaktyā labhyas tv ananyayā", "yasyāntaḥ-sthāni bhūtāni yena sarvam idaṃ tatam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Esa <a class=\"t\" href=\"glosario.html#purusa\" data-t=\"purusa\">Persona</a> suprema, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>, se alcanza con una <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">devoción</a> exclusiva: en ella están los seres, y por ella está penetrado todo esto.</span>", "palabras": [{"iast": "puruṣaḥ", "sa": "पुरुषः", "gram": "nom. sg. m.", "es": "la Persona", "ref": "purusa"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "esa"}, {"iast": "paraḥ", "sa": "परः", "gram": "nom. sg. m. adj.", "es": "suprema"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha"}, {"iast": "bhaktyā", "sa": "भक्त्या", "gram": "ins. sg. f.", "es": "con devoción", "ref": "bhakti", "analisis": "√bhaj (participar, adorar)"}, {"iast": "labhyaḥ", "sa": "लभ्यः", "gram": "nom. sg. m. gerundivo", "es": "se alcanza, alcanzable", "analisis": "√labh (obtener)"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero, en verdad"}, {"iast": "ananyayā", "sa": "अनन्यया", "gram": "ins. sg. f. adj.", "es": "exclusiva, que no tiene otro objeto", "analisis": "an (no) + anya (otro)"}, {"iast": "yasya", "sa": "यस्य", "gram": "gen. sg. m. rel.", "es": "de la cual"}, {"iast": "antaḥ-sthāni", "sa": "अन्तःस्थानि", "gram": "nom. pl. n. comp.", "es": "que están dentro", "analisis": "antar (dentro) + stha (que está)"}, {"iast": "bhūtāni", "sa": "भूतानि", "gram": "nom. pl. n.", "es": "los seres"}, {"iast": "yena", "sa": "येन", "gram": "ins. sg. m. rel.", "es": "por la cual"}, {"iast": "sarvam", "sa": "सर्वम्", "gram": "nom. sg. n.", "es": "todo"}, {"iast": "idam", "sa": "इदम्", "gram": "nom. sg. n. pron.", "es": "esto"}, {"iast": "tatam", "sa": "ततम्", "gram": "nom. sg. n. ppp", "es": "penetrado, extendido", "analisis": "√tan (extender)"}], "nota": "<p><em>Yena sarvam idaṃ tatam</em>, «por quien todo esto está penetrado» (de √tan, «extender»), es la fórmula que <a class=\"vref\" href=\"capitulo-02.html#v17\" data-v=\"2.17\">2.17</a> aplica a lo imperecedero; volverá en <a class=\"vref\" href=\"capitulo-18.html#v46\" data-v=\"18.46\">18.46</a>, y <a class=\"vref\" href=\"capitulo-09.html#v4\" data-v=\"9.4\">9.4</a> la dirá en primera persona. <em>Ananya</em>, «sin otro»: la devoción que no tiene otro objeto; es el adjetivo de <a class=\"vref\" href=\"capitulo-08.html#v14\" data-v=\"8.14\">8.14</a>, y la expresión <em>bhaktyā tv ananyayā</em> reaparece en <a class=\"vref\" href=\"capitulo-11.html#v54\" data-v=\"11.54\">11.54</a>.</p>", "interp": [{"titulo": "La devoción que es conocimiento", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> explica <em>puruṣa</em> por la etimología tradicional, «el que yace en la ciudad» del cuerpo, o «el que lo llena todo», y entiende la devoción exclusiva como la que tiene la forma del conocimiento y no tiene otro objeto que el sí-mismo. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> la entiende, en cambio, como la devoción que no busca otro refugio, y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, como la que está hecha de amor (<em>prema-lakṣaṇā</em>).</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Una meta más alta que el sí-mismo", "html": "<p>Para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, la Persona suprema de este verso es el propio Kṛṣṇa, distinto del sí-mismo individual de <a class=\"vref\" href=\"capitulo-08.html#v20\" data-v=\"8.20\">8.20</a>–<a class=\"vref\" href=\"capitulo-08.html#v21\" data-v=\"8.21\">8.21</a> y superior a él; es la meta del sabio de <a class=\"vref\" href=\"capitulo-07.html#v17\" data-v=\"7.17\">7.17</a>–<a class=\"vref\" href=\"capitulo-07.html#v18\" data-v=\"7.18\">7.18</a>, que sólo se alcanza con la devoción que no busca otra cosa.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "De lo no manifiesto a la Persona", "html": "<p>En tres versos el lenguaje pasa de lo impersonal a lo personal: de lo no manifiesto y lo imperecedero (<a class=\"vref\" href=\"capitulo-08.html#v20\" data-v=\"8.20\">8.20</a>–<a class=\"vref\" href=\"capitulo-08.html#v21\" data-v=\"8.21\">8.21</a>) a «mi morada» y a la Persona suprema que se alcanza con devoción. Si se trata de una misma realidad vista de dos maneras o de dos metas distintas es justamente lo que separa a las escuelas.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "lo-no-manifiesto-eterno"}, {"n": 23, "hablante": "krsna", "sa": ["यत्र काले त्वनावृत्तिमावृत्तिं चैव योगिनः ।", "प्रयाता यान्ति तं कालं वक्ष्यामि भरतर्षभ ॥२३॥"], "iast": ["yatra kāle tv anāvṛttim āvṛttiṃ caiva yoginaḥ", "prayātā yānti taṃ kālaṃ vakṣyāmi bharatarṣabha"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Te diré, oh <a class=\"t\" href=\"glosario.html#bharatarsabha\" data-t=\"bharatarsabha\">Bharatarṣabha</a>, en qué tiempo los <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yoguis</a>, al partir, van para no volver, y en cuál van para volver.</span>", "palabras": [{"iast": "yatra", "sa": "यत्र", "gram": "ind.", "es": "en el que"}, {"iast": "kāle", "sa": "काले", "gram": "loc. sg. m.", "es": "tiempo", "analisis": "kāla (tiempo; momento)"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pues, ahora bien"}, {"iast": "anāvṛttim", "sa": "अनावृत्तिम्", "gram": "ac. sg. f.", "es": "el no-retorno", "analisis": "an (no) + āvṛtti (retorno; ā-√vṛt, volver)"}, {"iast": "āvṛttim", "sa": "आवृत्तिम्", "gram": "ac. sg. f.", "es": "el retorno", "analisis": "ā-√vṛt (volver)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "también"}, {"iast": "yoginaḥ", "sa": "योगिनः", "gram": "nom. pl. m.", "es": "los yoguis", "ref": "yogin"}, {"iast": "prayātāḥ", "sa": "प्रयाताः", "gram": "nom. pl. m. ppp", "es": "habiendo partido, al partir", "analisis": "pra-√yā (partir; aquí, morir)"}, {"iast": "yānti", "sa": "यान्ति", "gram": "3 pl. pres. act.", "es": "van", "analisis": "√yā (ir)"}, {"iast": "tam", "sa": "तम्", "gram": "ac. sg. m. pron.", "es": "ese"}, {"iast": "kālam", "sa": "कालम्", "gram": "ac. sg. m.", "es": "tiempo"}, {"iast": "vakṣyāmi", "sa": "वक्ष्यामि", "gram": "1 sg. fut. act.", "es": "diré", "analisis": "√vac (decir)"}, {"iast": "bharatarṣabha", "sa": "भरतर्षभ", "gram": "voc. sg. m.", "es": "oh toro de los Bhāratas", "ref": "bharatarsabha", "analisis": "bharata + ṛṣabha (toro)"}], "nota": "<p><em>Anāvṛtti</em>: «el no-retorno», no volver a nacer; <em>āvṛtti</em>: «el retorno». <em>Prayātāḥ</em>: «los que han partido», es decir, los que mueren; es el mismo verbo de <em>prayāṇa-kāla</em>, «la hora de la partida», por la que preguntaba Arjuna en <a class=\"vref\" href=\"capitulo-08.html#v2\" data-v=\"8.2\">8.2</a>.</p>", "interp": [{"titulo": "Una doctrina de las Upaniṣads", "html": "<p>Los versos <a class=\"vref\" href=\"capitulo-08.html#v23\" data-v=\"8.23\">8.23</a>–<a class=\"vref\" href=\"capitulo-08.html#v26\" data-v=\"8.26\">8.26</a> resumen una doctrina de las <a class=\"t\" href=\"glosario.html#upanisad\" data-t=\"upanisad\">Upaniṣads</a>: la de los dos caminos del que muere, el de los dioses y el de los antepasados (<em>Chāndogya Upaniṣad</em> 5.10; <em>Bṛhad-āraṇyaka Upaniṣad</em> 6.2). La Gītā conserva las etapas —llama o fuego, día, quincena clara, semestre del norte; humo, noche, quincena oscura, semestre del sur—, pero abrevia el recorrido y sólo nombra el término de cada camino: brahman, o la luz de la luna y la vuelta (véase la ficha <a class=\"t\" href=\"glosario.html#devayana\" data-t=\"devayana\">devayāna</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Te diré, oh Bharatarṣabha, por qué camino los yoguis, al partir, van para no volver, y por cuál van para volver.", "nota": "<p><em>Kāla</em> es «tiempo», y así lo deja la traducción principal. Pero los versos siguientes llaman «caminos» (<em>gatī</em>, <a class=\"vref\" href=\"capitulo-08.html#v26\" data-v=\"8.26\">8.26</a>; <em>sṛtī</em>, <a class=\"vref\" href=\"capitulo-08.html#v27\" data-v=\"8.27\">8.27</a>) a lo que aquí es un «tiempo», y sus etapas, aunque lleven nombres de tiempos (día, noche, quincena, semestre), son las de un recorrido. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> (en su comentario a <a class=\"vref\" href=\"capitulo-08.html#v24\" data-v=\"8.24\">8.24</a>), <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> explican que el verso habla de «tiempo» porque la mayoría de esas etapas llevan nombres de tiempos, como se llama «bosque de mangos» a uno en que abundan los mangos; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> da la misma razón, sin el ejemplo, y él, Śrīdhara y Madhusūdana dicen expresamente que «tiempo» designa aquí el camino; <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> entiende que «tiempo» vale por todas las divinidades del camino, también las que no son de tiempo, como el fuego.</p>"}], "ens": "los-dos-caminos"}, {"n": 24, "hablante": "krsna", "sa": ["अग्निर्ज्योतिरहः शुक्लः षण्मासा उत्तरायणम् ।", "तत्र प्रयाता गच्छन्ति ब्रह्म ब्रह्मविदो जनाः ॥२४॥"], "iast": ["agnir jyotir ahaḥ śuklaḥ ṣaṇ-māsā uttarāyaṇam", "tatra prayātā gacchanti brahma brahma-vido janāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">El <a class=\"t\" href=\"glosario.html#agni\" data-t=\"agni\">fuego</a>, la luz, el día, la quincena clara, los seis meses del <a class=\"t\" href=\"glosario.html#uttarayana\" data-t=\"uttarayana\">curso norte del sol</a>: partiendo en ellos, los que conocen <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a> van a brahman.</span>", "palabras": [{"iast": "agniḥ", "sa": "अग्निः", "gram": "nom. sg. m.", "es": "el fuego", "ref": "agni"}, {"iast": "jyotiḥ", "sa": "ज्योतिः", "gram": "nom. sg. n.", "es": "la luz"}, {"iast": "ahaḥ", "sa": "अहः", "gram": "nom. sg. n.", "es": "el día"}, {"iast": "śuklaḥ", "sa": "शुक्लः", "gram": "nom. sg. m.", "es": "la quincena clara", "analisis": "śukla (claro, blanco), con pakṣa (quincena) sobrentendido"}, {"iast": "ṣaṇ-māsāḥ", "sa": "षण्मासाः", "gram": "nom. pl. m. comp.", "es": "los seis meses", "analisis": "ṣaṣ (seis) + māsa (mes)"}, {"iast": "uttarāyaṇam", "sa": "उत्तरायणम्", "gram": "nom. sg. n.", "es": "el curso norte del sol", "ref": "uttarayana", "analisis": "uttara (norte) + ayana (marcha, curso)"}, {"iast": "tatra", "sa": "तत्र", "gram": "ind.", "es": "allí, entonces"}, {"iast": "prayātāḥ", "sa": "प्रयाताः", "gram": "nom. pl. m. ppp", "es": "al partir", "analisis": "pra-√yā (partir)"}, {"iast": "gacchanti", "sa": "गच्छन्ति", "gram": "3 pl. pres. act.", "es": "van", "analisis": "√gam (ir)"}, {"iast": "brahma", "sa": "ब्रह्म", "gram": "ac. sg. n.", "es": "a brahman", "ref": "brahman"}, {"iast": "brahma-vidaḥ", "sa": "ब्रह्मविदः", "gram": "nom. pl. m. comp.", "es": "los que conocen brahman", "ref": "brahman", "analisis": "brahman + vid (que conoce; √vid)"}, {"iast": "janāḥ", "sa": "जनाः", "gram": "nom. pl. m.", "es": "los hombres, las personas"}], "nota": "<p><em>Śukla</em>, «claro, blanco», es la quincena clara (<em>śukla-pakṣa</em>), la de la luna creciente. <em>Uttarāyaṇa</em>: los seis meses en que el sol, después del solsticio de invierno, avanza hacia el norte (véase la ficha <a class=\"t\" href=\"glosario.html#uttarayana\" data-t=\"uttarayana\">uttarāyaṇa</a>). <em>Tatra prayātāḥ</em>: «partiendo allí» o «entonces»; la traducción conserva la ambigüedad entre el tiempo y el camino. <em>Brahma-vidaḥ</em>: «los que conocen brahman».</p>", "interp": [{"titulo": "El camino de los que meditan", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende que estos nombres designan las divinidades que presiden esos tiempos y forman el camino, y que «los que conocen brahman» son aquí los que meditan en brahman: llegan a él gradualmente, por este camino. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> precisa que se trata del brahman con atributos. El que ha alcanzado el conocimiento pleno no va a ninguna parte; para él, como dice la Upaniṣad, «sus alientos no salen» (<em>na tasya prāṇā utkrāmanti</em>, <em>Bṛhad-āraṇyaka Upaniṣad</em> 4.4.6). <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> lo dice casi con las mismas palabras.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Bhīṣma y el curso norte del sol", "html": "<p>En el <a class=\"t\" href=\"glosario.html#mahabharata\" data-t=\"mahabharata\">Mahābhārata</a>, <a class=\"t\" href=\"glosario.html#bhisma\" data-t=\"bhisma\">Bhīṣma</a>, que podía elegir el momento de su muerte, cae herido en la batalla y yace sobre un lecho de flechas hasta que el sol emprende su curso hacia el norte. El poema toma así la enumeración en su sentido literal: el curso norte del sol como el tiempo propicio para morir.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Guiados por las divinidades del fuego, de la luz, del día, de la quincena clara y de los seis meses del curso norte del sol, los que conocen brahman, al partir, van por ese camino a brahman.", "nota": "<p>Si los nombres del verso no designan momentos, sino las divinidades que presiden cada etapa y conducen al que parte: así lo entienden <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, en la línea de los <em>Brahma-sūtra</em> (4.3.4), que llaman «conductoras» (<em>ātivāhika</em>) a las divinidades del camino; Madhusūdana cita el sūtra. La traducción principal deja la enumeración como está. La lectura literal, la del momento de la muerte, tiene un ejemplo célebre en <a class=\"t\" href=\"glosario.html#bhisma\" data-t=\"bhisma\">Bhīṣma</a>, que esperó al curso norte del sol para morir (véase la ficha <a class=\"t\" href=\"glosario.html#uttarayana\" data-t=\"uttarayana\">uttarāyaṇa</a>).</p>"}], "ens": "los-dos-caminos"}, {"n": 25, "hablante": "krsna", "sa": ["धूमो रात्रिस्तथा कृष्णः षण्मासा दक्षिणायनम् ।", "तत्र चान्द्रमसं ज्योतिर्योगी प्राप्य निवर्तते ॥२५॥"], "iast": ["dhūmo rātris tathā kṛṣṇaḥ ṣaṇ-māsā dakṣiṇāyanam", "tatra cāndramasaṃ jyotir yogī prāpya nivartate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">El humo, la noche, y también la quincena oscura, los seis meses del <a class=\"t\" href=\"glosario.html#uttarayana\" data-t=\"uttarayana\">curso sur del sol</a>: partiendo en ellos, el <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yogui</a> alcanza la luz de la luna y vuelve.</span>", "palabras": [{"iast": "dhūmaḥ", "sa": "धूमः", "gram": "nom. sg. m.", "es": "el humo"}, {"iast": "rātriḥ", "sa": "रात्रिः", "gram": "nom. sg. f.", "es": "la noche"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "también, asimismo"}, {"iast": "kṛṣṇaḥ", "sa": "कृष्णः", "gram": "nom. sg. m.", "es": "la quincena oscura", "analisis": "kṛṣṇa (oscuro, negro), con pakṣa (quincena) sobrentendido"}, {"iast": "ṣaṇ-māsāḥ", "sa": "षण्मासाः", "gram": "nom. pl. m. comp.", "es": "los seis meses", "analisis": "ṣaṣ (seis) + māsa (mes)"}, {"iast": "dakṣiṇāyanam", "sa": "दक्षिणायनम्", "gram": "nom. sg. n.", "es": "el curso sur del sol", "ref": "uttarayana", "analisis": "dakṣiṇa (sur) + ayana (marcha, curso)"}, {"iast": "tatra", "sa": "तत्र", "gram": "ind.", "es": "allí, entonces"}, {"iast": "cāndramasam", "sa": "चान्द्रमसम्", "gram": "ac. sg. n. adj.", "es": "de la luna", "analisis": "candramas (la luna)"}, {"iast": "jyotiḥ", "sa": "ज्योतिः", "gram": "ac. sg. n.", "es": "la luz"}, {"iast": "yogī", "sa": "योगी", "gram": "nom. sg. m.", "es": "el yogui", "ref": "yogin"}, {"iast": "prāpya", "sa": "प्राप्य", "gram": "abs.", "es": "habiendo alcanzado", "analisis": "pra-√āp (alcanzar)"}, {"iast": "nivartate", "sa": "निवर्तते", "gram": "3 sg. pres. med.", "es": "vuelve", "analisis": "ni-√vṛt (volver atrás)"}], "nota": "<p><em>Kṛṣṇa</em>, «oscuro», es aquí la quincena oscura (<em>kṛṣṇa-pakṣa</em>), la de la luna menguante; la palabra es la misma que el nombre de <a class=\"t\" href=\"glosario.html#krsna\" data-t=\"krsna\">Kṛṣṇa</a>, pero no tiene que ver con él. <em>Dakṣiṇāyana</em>: el curso del sol hacia el sur. <em>Cāndramasaṃ jyotiḥ</em>: «la luz de la luna». <em>Nivartate</em>: «vuelve», a nacer en este mundo. Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, como para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, el «yogui» de este verso es el que se dedica a los ritos (<em>karmin</em>), no el que medita.</p>", "interp": [{"titulo": "La vuelta desde la luna", "html": "<p>En la <em>Chāndogya Upaniṣad</em> (5.10), los que han vivido entregados a los sacrificios, a las obras de utilidad pública y a los dones siguen el camino del humo hasta el mundo de los antepasados y la luna; allí permanecen mientras dura su mérito, y luego vuelven como lluvia, plantas y alimento, hasta nacer de nuevo. La Gītā lo resume en una palabra, «vuelve» (<em>nivartate</em>), y lo repetirá en <a class=\"vref\" href=\"capitulo-09.html#v20\" data-v=\"9.20\">9.20</a>–<a class=\"vref\" href=\"capitulo-09.html#v21\" data-v=\"9.21\">9.21</a>: agotado su mérito, entran de nuevo en el mundo de los mortales.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "los-dos-caminos"}, {"n": 26, "hablante": "krsna", "sa": ["शुक्लकृष्णे गती ह्येते जगतः शाश्वते मते ।", "एकया यात्यनावृत्तिमन्ययावर्तते पुनः ॥२६॥"], "iast": ["śukla-kṛṣṇe gatī hy ete jagataḥ śāśvate mate", "ekayā yāty anāvṛttim anyayāvartate punaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Estos dos <a class=\"t\" href=\"glosario.html#devayana\" data-t=\"devayana\">caminos</a>, el claro y el oscuro, se tienen por eternos para el mundo: por uno se va para no volver; por el otro se vuelve de nuevo.</span>", "palabras": [{"iast": "śukla-kṛṣṇe", "sa": "शुक्लकृष्णे", "gram": "nom. du. f. comp.", "es": "el claro y el oscuro", "analisis": "śukla (claro) + kṛṣṇa (oscuro)"}, {"iast": "gatī", "sa": "गती", "gram": "nom. du. f.", "es": "los dos caminos", "ref": "devayana", "analisis": "gati (ida, camino; √gam)"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "ete", "sa": "एते", "gram": "nom. du. f. pron.", "es": "estos dos"}, {"iast": "jagataḥ", "sa": "जगतः", "gram": "gen. sg. n.", "es": "del mundo"}, {"iast": "śāśvate", "sa": "शाश्वते", "gram": "nom. du. f. adj.", "es": "eternos"}, {"iast": "mate", "sa": "मते", "gram": "nom. du. f. ppp", "es": "tenidos por", "analisis": "√man (pensar, considerar)"}, {"iast": "ekayā", "sa": "एकया", "gram": "ins. sg. f.", "es": "por uno"}, {"iast": "yāti", "sa": "याति", "gram": "3 sg. pres. act.", "es": "va", "analisis": "√yā (ir)"}, {"iast": "anāvṛttim", "sa": "अनावृत्तिम्", "gram": "ac. sg. f.", "es": "al no-retorno", "analisis": "an (no) + āvṛtti (retorno)"}, {"iast": "anyayā", "sa": "अन्यया", "gram": "ins. sg. f.", "es": "por el otro"}, {"iast": "āvartate", "sa": "आवर्तते", "gram": "3 sg. pres. med.", "es": "vuelve", "analisis": "ā-√vṛt (volver)"}, {"iast": "punaḥ", "sa": "पुनः", "gram": "ind.", "es": "de nuevo"}], "nota": "<p><em>Śukla-kṛṣṇe gatī</em>: «los dos caminos, claro y oscuro», en dual, como los demás términos del verso. <em>Jagataḥ</em>: «del mundo». <em>Śāśvate mate</em>: «tenidos por eternos». <em>Ekayā… anyayā</em>: «por uno… por el otro».</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "los-dos-caminos"}, {"n": 27, "hablante": "krsna", "sa": ["नैते सृती पार्थ जानन्योगी मुह्यति कश्चन ।", "तस्मात्सर्वेषु कालेषु योगयुक्तो भवार्जुन ॥२७॥"], "iast": ["naite sṛtī pārtha jānan yogī muhyati kaścana", "tasmāt sarveṣu kāleṣu yoga-yukto bhavārjuna"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Conociendo estos dos caminos, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>, ningún <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yogui</a> se <a class=\"t\" href=\"glosario.html#moha\" data-t=\"moha\">extravía</a>. Por eso, oh <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>, sé en todo momento <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unido en yoga</a>.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ete", "sa": "एते", "gram": "ac. du. f. pron.", "es": "estos dos"}, {"iast": "sṛtī", "sa": "सृती", "gram": "ac. du. f.", "es": "los dos caminos", "ref": "devayana", "analisis": "sṛti (camino; √sṛ, correr, ir)"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh hijo de Pṛthā", "ref": "partha"}, {"iast": "jānan", "sa": "जानन्", "gram": "nom. sg. m. part.", "es": "conociendo", "analisis": "√jñā (conocer)"}, {"iast": "yogī", "sa": "योगी", "gram": "nom. sg. m.", "es": "el yogui", "ref": "yogin"}, {"iast": "muhyati", "sa": "मुह्यति", "gram": "3 sg. pres. act.", "es": "se extravía", "ref": "moha", "analisis": "√muh (extraviarse)"}, {"iast": "kaścana", "sa": "कश्चन", "gram": "nom. sg. m. pron.", "es": "ninguno (con na)"}, {"iast": "tasmāt", "sa": "तस्मात्", "gram": "ind.", "es": "por eso"}, {"iast": "sarveṣu", "sa": "सर्वेषु", "gram": "loc. pl. m.", "es": "en todos"}, {"iast": "kāleṣu", "sa": "कालेषु", "gram": "loc. pl. m.", "es": "los tiempos", "analisis": "kāla (tiempo)"}, {"iast": "yoga-yuktaḥ", "sa": "योगयुक्तः", "gram": "nom. sg. m. comp.", "es": "unido en yoga", "ref": "yukta", "analisis": "yoga + yukta (unido; √yuj)"}, {"iast": "bhava", "sa": "भव", "gram": "2 sg. impv. act.", "es": "sé", "analisis": "√bhū (ser)"}, {"iast": "arjuna", "sa": "अर्जुन", "gram": "voc. sg. m.", "es": "oh Arjuna", "ref": "arjuna"}], "nota": "<p><em>Sṛtī</em>: «los dos caminos», dual de <em>sṛti</em>, de √sṛ, «correr, ir». <em>Sarveṣu kāleṣu</em>: «en todos los tiempos», «en todo momento»; la misma expresión de <a class=\"vref\" href=\"capitulo-08.html#v7\" data-v=\"8.7\">8.7</a>.</p>", "interp": [{"titulo": "En todo momento", "html": "<p>Arjuna preguntó cómo se conoce a Kṛṣṇa «en la hora de la partida» (<a class=\"vref\" href=\"capitulo-08.html#v2\" data-v=\"8.2\">8.2</a>), y Kṛṣṇa anunció que diría «en qué tiempo» se parte para no volver (<a class=\"vref\" href=\"capitulo-08.html#v23\" data-v=\"8.23\">8.23</a>). La respuesta final deja atrás el cálculo: «en todos los tiempos» (<em>sarveṣu kāleṣu</em>), sé unido en yoga. Es la lógica de <a class=\"vref\" href=\"capitulo-08.html#v7\" data-v=\"8.7\">8.7</a>, con la misma expresión: quien recuerda a Kṛṣṇa en todo momento lo recordará también al morir.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "mas-alla-de-los-dos-caminos"}, {"n": 28, "hablante": "krsna", "sa": ["वेदेषु यज्ञेषु तपःसु चैव दानेषु यत्पुण्यफलं प्रदिष्टम् ।", "अत्येति तत्सर्वमिदं विदित्वा योगी परं स्थानमुपैति चाद्यम् ॥२८॥"], "iast": ["vedeṣu yajñeṣu tapaḥsu caiva dāneṣu yat puṇya-phalaṃ pradiṣṭam", "atyeti tat sarvam idaṃ viditvā yogī paraṃ sthānam upaiti cādyam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">El <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yogui</a> que conoce esto va más allá de todo el <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">fruto</a> meritorio que se atribuye a los <a class=\"t\" href=\"glosario.html#veda\" data-t=\"veda\">Vedas</a>, a los <a class=\"t\" href=\"glosario.html#yajna\" data-t=\"yajna\">sacrificios</a>, a las <a class=\"t\" href=\"glosario.html#tapas\" data-t=\"tapas\">austeridades</a> y a los dones, y alcanza el lugar supremo, el primero.</span>", "palabras": [{"iast": "vedeṣu", "sa": "वेदेषु", "gram": "loc. pl. m.", "es": "en los Vedas", "ref": "veda"}, {"iast": "yajñeṣu", "sa": "यज्ञेषु", "gram": "loc. pl. m.", "es": "en los sacrificios", "ref": "yajna"}, {"iast": "tapaḥsu", "sa": "तपःसु", "gram": "loc. pl. n.", "es": "en las austeridades", "ref": "tapas"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "también"}, {"iast": "dāneṣu", "sa": "दानेषु", "gram": "loc. pl. n.", "es": "en los dones", "analisis": "dāna (don; √dā, dar)"}, {"iast": "yat", "sa": "यत्", "gram": "nom. sg. n. rel.", "es": "el que"}, {"iast": "puṇya-phalam", "sa": "पुण्यफलम्", "gram": "nom. sg. n. comp.", "es": "fruto meritorio", "ref": "phala", "analisis": "puṇya (mérito) + phala (fruto)"}, {"iast": "pradiṣṭam", "sa": "प्रदिष्टम्", "gram": "nom. sg. n. ppp", "es": "asignado, indicado", "analisis": "pra-√diś (indicar, asignar)"}, {"iast": "atyeti", "sa": "अत्येति", "gram": "3 sg. pres. act.", "es": "va más allá", "analisis": "ati (más allá) + √i (ir)"}, {"iast": "tat", "sa": "तत्", "gram": "ac. sg. n. pron.", "es": "eso"}, {"iast": "sarvam", "sa": "सर्वम्", "gram": "ac. sg. n. adj.", "es": "todo"}, {"iast": "idam", "sa": "इदम्", "gram": "ac. sg. n. pron.", "es": "esto"}, {"iast": "viditvā", "sa": "विदित्वा", "gram": "abs.", "es": "habiendo conocido", "analisis": "√vid (saber)"}, {"iast": "yogī", "sa": "योगी", "gram": "nom. sg. m.", "es": "el yogui", "ref": "yogin"}, {"iast": "param", "sa": "परम्", "gram": "ac. sg. n. adj.", "es": "supremo"}, {"iast": "sthānam", "sa": "स्थानम्", "gram": "ac. sg. n.", "es": "lugar, morada", "analisis": "√sthā (estar)"}, {"iast": "upaiti", "sa": "उपैति", "gram": "3 sg. pres. act.", "es": "alcanza", "analisis": "upa + √i (ir hacia)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "ādyam", "sa": "आद्यम्", "gram": "ac. sg. n. adj.", "es": "primero, originario", "analisis": "ādi (comienzo)"}], "nota": "<p>Verso en metro <em>triṣṭubh</em>, como <a class=\"vref\" href=\"capitulo-08.html#v9\" data-v=\"8.9\">8.9</a>–<a class=\"vref\" href=\"capitulo-08.html#v11\" data-v=\"8.11\">8.11</a>. <em>Puṇya-phala</em>: «el fruto del mérito». <em>Pradiṣṭam</em>: «indicado, asignado» (por las escrituras). <em>Idaṃ viditvā</em>: «habiendo conocido esto». <em>Ādyam</em>: «primero, originario».</p>", "interp": [{"titulo": "Más allá de los frutos", "html": "<p>El verso cierra el capítulo con una idea que recorre los anteriores: los frutos del Veda, de los sacrificios, de la austeridad y de los dones son reales, pero se acaban (véanse <a class=\"vref\" href=\"capitulo-02.html#v42\" data-v=\"2.42\">2.42</a>–<a class=\"vref\" href=\"capitulo-02.html#v46\" data-v=\"2.46\">2.46</a>, <a class=\"vref\" href=\"capitulo-07.html#v23\" data-v=\"7.23\">7.23</a> y, enseguida, <a class=\"vref\" href=\"capitulo-09.html#v20\" data-v=\"9.20\">9.20</a>–<a class=\"vref\" href=\"capitulo-09.html#v21\" data-v=\"9.21\">9.21</a>). El yogui que comprende esto los deja atrás y alcanza «el lugar supremo, el primero», aquel del que no se vuelve (<a class=\"vref\" href=\"capitulo-08.html#v21\" data-v=\"8.21\">8.21</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Lo que hay que conocer", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> entienden «esto» (<em>idam</em>) como todo lo enseñado en el capítulo en respuesta a las siete preguntas de Arjuna (<a class=\"vref\" href=\"capitulo-08.html#v1\" data-v=\"8.1\">8.1</a>–<a class=\"vref\" href=\"capitulo-08.html#v2\" data-v=\"8.2\">8.2</a>), comprendido y puesto en práctica.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "triṣṭubh (cuatro pies de once sílabas)", "ens": "mas-alla-de-los-dos-caminos"}], "ensenanzas": [{"id": "las-definiciones-de-krsna", "desde": 3, "hasta": 4, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Brahman, el sí-mismo, la acción, los seres, los dioses y el sacrificio", "resumen": "<p>A las siete preguntas de Arjuna (<a class=\"vref\" href=\"capitulo-08.html#v1\" data-v=\"8.1\">8.1</a>–<a class=\"vref\" href=\"capitulo-08.html#v2\" data-v=\"8.2\">8.2</a>) Kṛṣṇa responde primero con seis definiciones breves. Brahman es lo imperecedero supremo. Lo relativo al sí-mismo es la naturaleza propia. La acción es la emisión que hace surgir a los seres. Lo relativo a los seres es lo perecedero; lo relativo a los dioses, el puruṣa; y lo relativo al sacrificio es él mismo, presente en el cuerpo. Así, los términos con que la tradición védica describía el mundo, la persona y el rito quedan ordenados y referidos a Kṛṣṇa. La séptima pregunta —cómo se le conoce en la hora de la muerte— la responde el resto del capítulo.</p>"}, {"id": "lo-que-se-recuerda-al-morir", "desde": 5, "hasta": 6, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Lo que se recuerda al morir", "resumen": "<p>Se va a aquello que se recuerda en la hora de la muerte: quien parte recordando a Kṛṣṇa llega a su ser, y quien recuerda otra cosa va a esa otra cosa. Pero ese último recuerdo no se elige en el momento: es aquello de lo que uno ha vivido impregnado. La muerte no cambia la dirección de una vida; la revela.</p>"}, {"id": "recordar-siempre-y-luchar", "desde": 7, "hasta": 7, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Recordarlo en todo momento, sin dejar de actuar", "resumen": "<p>Como el último recuerdo depende del de toda la vida, la preparación para la muerte es recordar a Kṛṣṇa en todo momento, con la mente y el entendimiento entregados a él. Y no en lugar de la acción, sino mientras se actúa: «recuérdame y lucha». Es la misma unión de devoción y deber de <a class=\"vref\" href=\"capitulo-03.html#v30\" data-v=\"3.30\">3.30</a>.</p>"}, {"id": "partir-con-el-aliento-entre-las-cejas", "desde": 8, "hasta": 10, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "La práctica constante y la hora de la partida", "resumen": "<p>Dos tiempos de una misma disciplina. En la vida, el yoga de la práctica: el pensamiento vuelto una y otra vez hacia la Persona suprema, sin ir tras otra cosa. En la hora de la muerte, la mente inmóvil, la devoción y la fuerza del yoga, y el aliento vital llevado entre las cejas, el punto donde <a class=\"vref\" href=\"capitulo-05.html#v27\" data-v=\"5.27\">5.27</a> fijaba la mirada. Quien así parte llega a la Persona suprema, el vidente antiguo «del color del sol, más allá de la oscuridad». La técnica continúa en <a class=\"vref\" href=\"capitulo-08.html#v12\" data-v=\"8.12\">8.12</a>–<a class=\"vref\" href=\"capitulo-08.html#v13\" data-v=\"8.13\">8.13</a>.</p>"}, {"id": "partir-pronunciando-om", "desde": 11, "hasta": 13, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Partir pronunciando oṃ", "resumen": "<p>Kṛṣṇa describe cómo dejar el cuerpo: cerrar las puertas de los sentidos, recoger la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> en el corazón, llevar el <a class=\"t\" href=\"glosario.html#prana\" data-t=\"prana\">aliento vital</a> a la cabeza y, firme en la <a class=\"t\" href=\"glosario.html#dharana\" data-t=\"dharana\">concentración</a> del yoga, pronunciar <a class=\"t\" href=\"glosario.html#om\" data-t=\"om\">oṃ</a>, «la sílaba única que es brahman», recordándolo a él. Quien parte así alcanza la meta suprema. Completa la indicación de <a class=\"vref\" href=\"capitulo-08.html#v10\" data-v=\"8.10\">8.10</a> y recoge, para la hora de la muerte, la disciplina de la meditación del capítulo 6 (<a class=\"vref\" href=\"capitulo-06.html#v10\" data-v=\"6.10\">6.10</a>–<a class=\"vref\" href=\"capitulo-06.html#v26\" data-v=\"6.26\">6.26</a>).</p>"}, {"id": "facil-de-alcanzar", "desde": 14, "hasta": 16, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Fácil de alcanzar para quien lo recuerda siempre", "resumen": "<p>A quien lo <a class=\"t\" href=\"glosario.html#smarana\" data-t=\"smarana\">recuerda</a> sin cesar, sin pensar en otra cosa, Kṛṣṇa le es «fácil de alcanzar». Quien llega a él no vuelve a nacer, mientras que de todos los demás mundos, incluido el de <a class=\"t\" href=\"glosario.html#brahmaloka\" data-t=\"brahmaloka\">Brahmā</a>, se vuelve. Frente a la técnica de los versos anteriores, el capítulo propone aquí un camino que no depende del instante de la muerte, sino de toda una vida de recuerdo.</p>"}, {"id": "el-dia-y-la-noche-de-brahma", "desde": 17, "hasta": 19, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El día y la noche de Brahmā", "resumen": "<p>El tiempo cósmico tiene su propio ritmo: un día de <a class=\"t\" href=\"glosario.html#brahma-deva\" data-t=\"brahma-deva\">Brahmā</a> dura mil eras, y su noche otras mil (<a class=\"vref\" href=\"capitulo-08.html#v17\" data-v=\"8.17\">8.17</a>). Al llegar el día, todo lo manifiesto surge de lo no manifiesto; al llegar la noche, se disuelve en él (<a class=\"vref\" href=\"capitulo-08.html#v18\" data-v=\"8.18\">8.18</a>). Y son los mismos seres los que vuelven una y otra vez, sin poder evitarlo (<a class=\"vref\" href=\"capitulo-08.html#v19\" data-v=\"8.19\">8.19</a>). La enseñanza está en el contexto: si de todos los mundos se vuelve, incluido el de Brahmā (<a class=\"vref\" href=\"capitulo-08.html#v16\" data-v=\"8.16\">8.16</a>), nada de lo que nace dentro del ciclo es una meta definitiva.</p>"}, {"id": "lo-no-manifiesto-eterno", "desde": 20, "hasta": 22, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Más allá del ciclo: lo no manifiesto eterno y la Persona suprema", "resumen": "<p>Por encima de lo no manifiesto del que surgen y en el que se disuelven los seres hay otra realidad, eterna, que no perece cuando todo perece (<a class=\"vref\" href=\"capitulo-08.html#v20\" data-v=\"8.20\">8.20</a>). Se la llama lo <a class=\"t\" href=\"glosario.html#aksara\" data-t=\"aksara\">imperecedero</a> y la meta suprema: quien la alcanza no vuelve; es la morada suprema de Kṛṣṇa (<a class=\"vref\" href=\"capitulo-08.html#v21\" data-v=\"8.21\">8.21</a>). Esa Persona suprema, en la que están todos los seres y por la que todo está penetrado, se alcanza con una devoción exclusiva (<a class=\"vref\" href=\"capitulo-08.html#v22\" data-v=\"8.22\">8.22</a>). <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> ve en lo no manifiesto eterno y en la Persona suprema dos metas distintas; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, una misma realidad (véanse las interpretaciones de los versos).</p>"}, {"id": "los-dos-caminos", "desde": 23, "hasta": 26, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Los dos caminos: el que no vuelve y el que vuelve", "resumen": "<p>Al morir se parte por uno de dos caminos: el claro —fuego, luz, día, quincena clara, curso norte del sol—, que lleva a <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a> sin retorno, o el oscuro —humo, noche, quincena oscura, curso sur—, que lleva a la luz de la luna y de vuelta a nacer. Kṛṣṇa recoge aquí una doctrina de las Upaniṣads (véase <a class=\"t\" href=\"glosario.html#devayana\" data-t=\"devayana\">devayāna</a>).</p>"}, {"id": "mas-alla-de-los-dos-caminos", "desde": 27, "hasta": 28, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Más allá de los dos caminos: unido en yoga en todo momento", "resumen": "<p>Conocer los dos caminos libra del extravío, y la conclusión no es calcular la hora de la muerte, sino vivir siempre <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unido en yoga</a>. El yogui que lo comprende deja atrás los frutos del Veda, del sacrificio, de la austeridad y de los dones, y alcanza el lugar supremo.</p>"}]};
